export const CATS = {"cities":"Cities","trade":"Trade","wine":"Wine","art":"Art","people":"People","geo":"Geography"};
export const PLACES = [
{"id":"ci-01","cat":"cities","name":"Tokyo","lat":35.68,"lon":139.69,"note":"Japan's capital and the world's largest urban area, about 37 million people. Finance and electronics, and the Tokyo Commodity Exchange's rubber and gold contracts.","country":"Japan","region":"Asia","about":"tokyo"},
{"id":"ci-02","cat":"cities","name":"Delhi","lat":28.61,"lon":77.21,"note":"India's capital, about 34 million in the urban area; New Delhi is the administrative district. The hub of north India's grain and sugar trade.","country":"India","region":"Asia","about":"delhi"},
{"id":"ci-03","cat":"cities","name":"Shanghai","lat":31.23,"lon":121.47,"note":"China's largest city and financial centre, around 30 million. Home of the Shanghai Futures Exchange (copper, steel, fuel oil) and the world's busiest container port.","country":"China","region":"Asia","about":"shanghai"},
{"id":"ci-04","cat":"cities","name":"Lagos","lat":6.52,"lon":3.38,"note":"Nigeria's commercial capital and largest city, 16 million or more. The country's ports and, at Lekki, the Dangote refinery; the oil money flows through here even though Abuja is the capital.","country":"Nigeria","region":"Africa","about":"lagos"},
{"id":"ci-05","cat":"cities","name":"Mexico City","lat":19.43,"lon":-99.13,"note":"Mexico's capital, about 22 million in the valley at 2,240 m. Pemex's headquarters and the seat of the world's oldest continuously run city in the Americas.","country":"Mexico","region":"North America","about":"mexico-city"},
{"id":"ci-06","cat":"cities","name":"Cairo","lat":30.04,"lon":31.24,"note":"Egypt's capital on the Nile, about 22 million in the urban area; the Suez Canal Authority's revenue and Egypt's wheat imports, the world's largest, are decided here.","country":"Egypt","region":"Africa","about":"cairo"},
{"id":"ci-07","cat":"cities","name":"Istanbul","lat":41.01,"lon":28.98,"note":"Turkey's largest city, on both sides of the Bosporus, about 16 million. The only city on two continents; every tanker out of the Black Sea passes it.","country":"Turkey","region":"Europe","about":"istanbul"},
{"id":"ci-08","cat":"cities","name":"Buenos Aires","lat":-34.6,"lon":-58.38,"note":"Argentina's capital on the Río de la Plata, about 15 million in the metro area. The Rosario–Buenos Aires river ports ship the country's soybeans, meal and corn.","country":"Argentina","region":"South America","about":"buenos-aires"},
{"id":"ci-09","cat":"cities","name":"Nairobi","lat":-1.29,"lon":36.82,"note":"Kenya's capital, about 5 million, at 1,800 m. East Africa's business hub and the Nairobi Coffee Exchange's auctions.","country":"Kenya","region":"Africa","about":"nairobi"},
{"id":"ci-10","cat":"cities","name":"Tallinn","lat":59.44,"lon":24.75,"note":"Estonia's capital on the Gulf of Finland, about 455,000, a medieval old town and a digital state. Its port, Muuga, was a major Russian oil transit terminal until 2022.","country":"Estonia","region":"Europe","about":"tallinn"},
{"id":"ci-11","cat":"cities","name":"Geneva","lat":46.2,"lon":6.14,"note":"Switzerland's second city on Lake Geneva, about 204,000 in the city. The capital of commodity trading: Trafigura, Vitol, Gunvor, Mercuria and Cargill's trading arm sit within a few streets.","country":"Switzerland","region":"Europe","about":"geneva"},
{"id":"ci-12","cat":"cities","name":"Zürich","lat":47.38,"lon":8.54,"note":"Switzerland's largest city, about 430,000, its banking and insurance centre; Glencore is an hour away in Zug, and the Kunsthaus holds the country's great collection.","country":"Switzerland","region":"Europe","about":"zurich"},
{"id":"ci-13","cat":"cities","name":"Singapore","lat":1.29,"lon":103.85,"note":"A city-state of 5.9 million at the tip of the Malay Peninsula: the world's largest bunkering port, Asia's oil trading and pricing hub, and the home of Platts' Asian assessments.","country":"Malaysia","region":"Asia","about":"singapore-2"},
{"id":"ci-14","cat":"cities","name":"Dubai","lat":25.2,"lon":55.27,"note":"The UAE's commercial city, about 3.6 million. Jebel Ali port, the DMCC free zone's gold and diamond trade, and the Dubai crude benchmark for Middle East exports to Asia.","country":"the United Arab Emirates","region":"Asia","about":"dubai"},
{"id":"ci-15","cat":"cities","name":"Doha","lat":25.29,"lon":51.53,"note":"Qatar's capital, about 2.4 million in the metro area, built on LNG money; QatarEnergy is headquartered here and Ras Laffan is an hour up the coast.","country":"Qatar","region":"Asia","about":"doha"},
{"id":"ci-16","cat":"cities","name":"Riyadh","lat":24.69,"lon":46.72,"note":"Saudi Arabia's capital in the Najd, about 7 million. Aramco's decisions are taken in Dhahran, but oil policy, OPEC positions and the sovereign fund are run from here.","country":"Saudi Arabia","region":"Asia","about":"riyadh"},
{"id":"ci-17","cat":"cities","name":"Tehran","lat":35.69,"lon":51.39,"note":"Iran's capital, about 9 million in the city and 15 million around it, at the foot of the Alborz. The National Iranian Oil Company and the ministry that sets Iran's export policy.","country":"Iran","region":"Asia","about":"tehran"},
{"id":"ci-18","cat":"cities","name":"Baku","lat":40.41,"lon":49.87,"note":"Azerbaijan's capital on the Caspian, about 2.3 million. The birthplace of the oil industry in the 1870s (the Nobels and Rothschilds drilled here) and the start of the Baku–Tbilisi–Ceyhan pipeline.","country":"Azerbaijan","region":"Asia","about":"baku"},
{"id":"ci-19","cat":"cities","name":"Astana","lat":51.17,"lon":71.43,"note":"Kazakhstan's capital since 1997, built on the steppe, about 1.4 million. The country's oil comes from Tengiz and Kashagan far to the west, its uranium from the south.","country":"Kazakhstan","region":"Asia","about":"astana"},
{"id":"ci-20","cat":"cities","name":"Ulaanbaatar","lat":47.92,"lon":106.92,"note":"Mongolia's capital, about 1.7 million, the coldest national capital. Copper from Oyu Tolgoi and coal from Tavan Tolgoi go south to China by truck and rail.","country":"Mongolia","region":"Asia","about":"ulaanbaatar"},
{"id":"ci-21","cat":"cities","name":"Lima","lat":-12.05,"lon":-77.04,"note":"Peru's capital on the Pacific coast, about 11 million. The world's second copper producer and a top silver, zinc and gold miner runs its trade from here; Callao is the port.","country":"Peru","region":"South America","about":"lima"},
{"id":"ci-22","cat":"cities","name":"Santiago de Chile","lat":-33.45,"lon":-70.67,"note":"Chile's capital in a valley below the Andes, about 7 million. Codelco, the world's largest copper producer, and SQM's lithium are headquartered here.","country":"Chile","region":"South America","about":"santiago-de-chile"},
{"id":"ci-23","cat":"cities","name":"Bogotá","lat":4.71,"lon":-74.07,"note":"Colombia's capital on a high plateau at 2,640 m, about 11 million. Coffee, coal from Cerrejón and Ecopetrol's crude are the exports it manages.","country":"Colombia","region":"South America","about":"bogota"},
{"id":"ci-24","cat":"cities","name":"Caracas","lat":10.48,"lon":-66.9,"note":"Venezuela's capital in a valley near the coast, about 3 million. PDVSA's headquarters, and the capital of the world's largest proven oil reserves, mostly heavy Orinoco crude.","country":"Venezuela","region":"South America","about":"caracas"},
{"id":"ci-25","cat":"cities","name":"Accra","lat":5.6,"lon":-0.19,"note":"Ghana's capital on the Gulf of Guinea, about 2.6 million in the city. Cocoa (the world's second producer), gold and Jubilee-field oil are the economy.","country":"Ghana","region":"Africa","about":"accra"},
{"id":"ci-26","cat":"cities","name":"Addis Ababa","lat":9.03,"lon":38.74,"note":"Ethiopia's capital at 2,350 m, about 5 million, and the African Union's seat. Coffee was first cultivated in these highlands and remains the country's main export.","country":"Ethiopia","region":"Africa","about":"addis-ababa"},
{"id":"ci-27","cat":"cities","name":"Kinshasa","lat":-4.32,"lon":15.31,"note":"The Democratic Republic of the Congo's capital on the Congo River, about 17 million, facing Brazzaville across the water. The country's cobalt and copper come from Katanga, 2,000 km away.","country":"the Democratic Republic of the Congo","region":"Africa","about":"kinshasa"},
{"id":"ci-28","cat":"cities","name":"Luanda","lat":-8.84,"lon":13.23,"note":"Angola's capital and port, about 9 million. Sub-Saharan Africa's second oil producer; the offshore blocks are run from here and the crude goes mostly to China.","country":"Angola","region":"Africa","about":"luanda"},
{"id":"ci-29","cat":"cities","name":"Perth","lat":-31.95,"lon":115.86,"note":"Western Australia's capital on the Swan River, about 2.2 million, the most isolated big city on Earth. Iron ore, LNG, gold and lithium are all managed from here.","country":"Australia","region":"Oceania","about":"perth"},
{"id":"ci-30","cat":"cities","name":"Auckland","lat":-36.85,"lon":174.76,"note":"New Zealand's largest city, about 1.7 million, between two harbours. Dairy is the country's biggest export; the Marlborough wines ship from further south.","country":"New Zealand","region":"Oceania","about":"auckland"},
{"id":"ci-31","cat":"cities","name":"Vancouver","lat":49.28,"lon":-123.12,"note":"Canada's Pacific port city, about 2.6 million. Grain, potash, coal and, since the Trans Mountain expansion, crude leave from here for Asia; many of the world's junior miners are listed on its exchange.","country":"Canada","region":"North America","about":"vancouver"},
{"id":"ci-32","cat":"cities","name":"Houston","lat":29.76,"lon":-95.37,"note":"Texas's largest city, about 7 million in the metro area: the energy capital of the United States, home of ExxonMobil, Chevron's trading, Phillips 66 and the refining belt along the Ship Channel.","country":"the United States","region":"North America","about":"houston"},
{"id":"ci-33","cat":"cities","name":"Reykjavík","lat":64.15,"lon":-21.94,"note":"Iceland's capital, about 140,000, heated by geothermal water; aluminium smelted on cheap hydropower and fish are the exports.","country":"Iceland","region":"Europe","about":"reykjavik"},
{"id":"ci-34","cat":"cities","name":"Tbilisi","lat":41.72,"lon":44.79,"note":"Georgia's capital on the Kura River, about 1.2 million. The Baku–Tbilisi–Ceyhan pipeline and the Baku–Supsa line cross the country to the Black Sea.","country":"Georgia","region":"Asia","about":"tbilisi"},
{"id":"ci-35","cat":"cities","name":"Almaty","lat":43.24,"lon":76.89,"note":"Kazakhstan's largest city and former capital, about 2 million, below the Tien Shan. The country's financial centre; its name comes from the apple, which was domesticated here.","country":"Kazakhstan","region":"Asia","about":"almaty"},
{"id":"ci-36","cat":"cities","name":"Hanoi","lat":21.03,"lon":105.85,"note":"Vietnam's capital on the Red River, about 8 million. The country is the world's second coffee exporter (robusta) and a major rice and cashew exporter.","country":"Vietnam","region":"Asia","about":"hanoi"},
{"id":"ci-37","cat":"cities","name":"Manila","lat":14.6,"lon":120.98,"note":"The Philippines' capital on Manila Bay, about 14 million in Metro Manila. The world's largest nickel ore exporter sends its ore from the islands further south.","country":"the Philippines","region":"Asia","about":"manila"},
{"id":"ci-38","cat":"cities","name":"Jakarta","lat":-6.21,"lon":106.85,"note":"Indonesia's capital on Java's north coast, about 11 million in the city and 30 million around it. Palm oil, nickel, coal and the world's largest archipelago's trade are run from here.","country":"Indonesia","region":"Asia","about":"jakarta"},
{"id":"ci-39","cat":"cities","name":"Dhaka","lat":23.81,"lon":90.41,"note":"Bangladesh's capital on the Buriganga, about 24 million in the urban area and among the world's densest. Garments are the export; the port is Chittagong.","country":"Bangladesh","region":"Asia","about":"dhaka"},
{"id":"ci-40","cat":"cities","name":"Karachi","lat":24.86,"lon":67.01,"note":"Pakistan's largest city and port on the Arabian Sea, about 20 million. The country's LNG imports and its cotton and rice exports pass through it.","country":"Pakistan","region":"Asia","about":"karachi"},
{"id":"ci-41","cat":"cities","name":"Mumbai","lat":19.08,"lon":72.88,"note":"India's financial capital on the Arabian Sea, about 21 million. The Reserve Bank, the stock exchanges, Reliance's headquarters and Bollywood; Nhava Sheva is the container port.","country":"India","region":"Asia","about":"mumbai"},
{"id":"ci-42","cat":"cities","name":"Chennai","lat":13.08,"lon":80.27,"note":"The capital of Tamil Nadu on the Bay of Bengal, about 11 million. South India's car industry and port; the Coromandel Coast was the East India Company's first foothold.","country":"India","region":"Asia","about":"chennai"},
{"id":"ci-43","cat":"cities","name":"Kolkata","lat":22.57,"lon":88.36,"note":"West Bengal's capital on the Hooghly, about 15 million, the former capital of British India and still the port for the jute, tea and coal of the east.","country":"India","region":"Asia","about":"kolkata"},
{"id":"ci-44","cat":"cities","name":"Johannesburg","lat":-26.2,"lon":28.04,"note":"South Africa's largest city, about 6 million, built on the Witwatersrand gold reef in 1886. The JSE and the headquarters of the mining houses; the gold is largely mined out.","country":"South Africa","region":"Africa","about":"johannesburg"},
{"id":"ci-45","cat":"cities","name":"Cape Town","lat":-33.93,"lon":18.42,"note":"South Africa's legislative capital at the foot of Table Mountain, about 4.8 million. Stellenbosch and Franschhoek are an hour away; the Cape of Good Hope is the tanker route when Suez closes.","country":"South Africa","region":"Africa","about":"cape-town"},
{"id":"ci-46","cat":"cities","name":"Casablanca","lat":33.57,"lon":-7.59,"note":"Morocco's largest city and port, about 3.7 million. Phosphates, where Morocco holds most of the world's reserves, ship from Jorf Lasfar and Casablanca.","country":"Morocco","region":"Africa","about":"casablanca"},
{"id":"ci-47","cat":"cities","name":"Algiers","lat":36.75,"lon":3.06,"note":"Algeria's capital on a bay of the Mediterranean, about 3 million. Sonatrach, Africa's largest company, runs the gas that goes to Spain and Italy by pipeline from here.","country":"Algeria","region":"Africa","about":"algiers"},
{"id":"ci-48","cat":"cities","name":"Tunis","lat":36.81,"lon":10.17,"note":"Tunisia's capital, about 2.7 million in the metro area, beside the ruins of Carthage. Olive oil (one of the world's largest exporters), phosphates and dates are the trade.","country":"Tunisia","region":"Africa","about":"tunis"},
{"id":"ci-49","cat":"cities","name":"Khartoum","lat":15.5,"lon":32.56,"note":"Sudan's capital at the meeting of the Blue and White Nile, about 6 million. Gum arabic, where Sudan supplies most of the world, and gold leave through Port Sudan.","country":"Sudan","region":"Africa","about":"khartoum"},
{"id":"ci-50","cat":"cities","name":"Lisbon","lat":38.72,"lon":-9.14,"note":"Portugal's capital on the Tagus estuary, about 2.9 million in the metro area. The Age of Discovery sailed from here; the port of Sines, to the south, is the deep-water one.","country":"Portugal","region":"Europe","about":"lisbon"},
{"id":"ci-51","cat":"cities","name":"Warsaw","lat":52.23,"lon":21.01,"note":"Poland's capital on the Vistula, about 1.8 million, rebuilt after 1945. The EU's largest coal producer and a growing LNG importer at Świnoujście.","country":"Poland","region":"Europe","about":"warsaw"},
{"id":"ci-52","cat":"cities","name":"Kyiv","lat":50.45,"lon":30.52,"note":"Ukraine's capital on the Dnieper, about 3 million. The country's grain, sunflower oil (the world's largest exporter) and steel are shipped from Odesa.","country":"Ukraine","region":"Europe","about":"kyiv"},
{"id":"ci-53","cat":"cities","name":"Bucharest","lat":44.43,"lon":26.1,"note":"Romania's capital, about 1.8 million. The country was Europe's first oil producer (Ploiești, 1857) and still has OMV Petrom and Black Sea gas.","country":"Romania","region":"Europe","about":"bucharest"},
{"id":"ci-54","cat":"cities","name":"Athens","lat":37.98,"lon":23.73,"note":"Greece's capital, about 3.6 million, below the Acropolis. Greek owners control the world's largest tanker fleet, run from Piraeus.","country":"Greece","region":"Europe","about":"athens"},
{"id":"ci-55","cat":"cities","name":"Helsinki","lat":60.17,"lon":24.94,"note":"Finland's capital on the Gulf of Finland, about 1.5 million in the region. Forest products, Neste's renewable diesel (its refinery is at Porvoo), and the busiest passenger port in Europe.","country":"Finland","region":"Europe","about":"helsinki"},
{"id":"ci-56","cat":"cities","name":"Oslo","lat":59.91,"lon":10.75,"note":"Norway's capital at the head of its fjord, about 1 million. Equinor's listing, the sovereign wealth fund, and the shipping and shipbroking offices that fix much of the world's tanker trade.","country":"Norway","region":"Europe","about":"oslo"},
{"id":"ci-57","cat":"cities","name":"Dublin","lat":53.35,"lon":-6.26,"note":"Ireland's capital on the Liffey, about 1.4 million in the metro area. The European headquarters of the big US tech firms, and a whiskey and dairy exporter.","country":"Ireland","region":"Europe","about":"dublin"},
{"id":"ci-58","cat":"cities","name":"Edinburgh","lat":55.95,"lon":-3.19,"note":"Scotland's capital, about 550,000, on volcanic crags. Banking, the Festival, and the whisky industry's head offices; the North Sea oil is run from Aberdeen.","country":"the United Kingdom","region":"Europe","about":"edinburgh"},
{"id":"ci-59","cat":"cities","name":"Munich","lat":48.14,"lon":11.58,"note":"Bavaria's capital, about 1.5 million. BMW, Siemens, Allianz and Munich Re; the Oktoberfest, and the breweries that gave the beer purity law its home.","country":"Germany","region":"Europe","about":"munich"},
{"id":"ci-60","cat":"cities","name":"Hamburg","lat":53.55,"lon":9.99,"note":"Germany's second city and largest port on the Elbe, about 1.9 million. Europe's third container port, the Hanseatic League's great survivor, and a coffee and cocoa importing centre.","country":"Germany","region":"Europe","about":"hamburg"},
{"id":"ci-61","cat":"cities","name":"Vienna","lat":48.21,"lon":16.37,"note":"Austria's capital on the Danube, about 2 million. OPEC's headquarters since 1965; the oil ministers meet here, and OMV is based here too.","country":"Austria","region":"Europe","about":"vienna"},
{"id":"ci-62","cat":"cities","name":"Prague","lat":50.08,"lon":14.44,"note":"The Czech capital on the Vltava, about 1.3 million, the best-preserved big city of central Europe. Škoda cars and the Pilsner brewed an hour away.","country":"the Czech Republic","region":"Europe","about":"prague"},
{"id":"ci-63","cat":"cities","name":"Budapest","lat":47.5,"lon":19.04,"note":"Hungary's capital on the Danube, about 1.7 million, Buda on the hills and Pest on the plain. MOL, central Europe's oil company, and the Tokaj wine region to the north-east.","country":"Hungary","region":"Europe","about":"budapest"},
{"id":"ci-64","cat":"cities","name":"Belgrade","lat":44.79,"lon":20.47,"note":"Serbia's capital where the Sava meets the Danube, about 1.7 million. The Danube barge trade, and Zijin's copper mine at Bor.","country":"Serbia","region":"Europe","about":"belgrade"},
{"id":"ci-65","cat":"cities","name":"Marseille","lat":43.3,"lon":5.37,"note":"France's second city and largest port, about 1.6 million. Fos-sur-Mer, its oil and container port, feeds the Mediterranean refineries and the pipelines to Switzerland and Germany.","country":"France","region":"Europe","about":"marseille"},
{"id":"ci-66","cat":"cities","name":"Milan","lat":45.46,"lon":9.19,"note":"Italy's financial and fashion capital, about 3.2 million in the metro area. The Borsa, Eni's trading, and Piedmont's wines two hours west.","country":"Italy","region":"Europe","about":"milan"},
{"id":"ci-67","cat":"cities","name":"Naples","lat":40.85,"lon":14.27,"note":"Italy's third city, about 3 million in the metro area, under Vesuvius. The port, Pompeii, and pizza, which was born here.","country":"Italy","region":"Europe","about":"naples"},
{"id":"ci-68","cat":"cities","name":"Seville","lat":37.39,"lon":-5.99,"note":"Andalusia's capital on the Guadalquivir, about 1.5 million. The Americas' silver landed here in the 16th century; orange groves and olive oil are the trade now.","country":"Spain","region":"Europe","about":"seville"},
{"id":"ci-69","cat":"cities","name":"Barcelona","lat":41.39,"lon":2.17,"note":"Catalonia's capital on the Mediterranean, about 5.5 million in the metro area. Gaudí's city; the port handles cars, chemicals and much of Spain's LNG.","country":"Spain","region":"Europe","about":"barcelona"},
{"id":"ci-70","cat":"cities","name":"Porto","lat":41.15,"lon":-8.61,"note":"Portugal's second city at the mouth of the Douro, about 1.7 million in the metro area. Port wine is shipped from the lodges at Vila Nova de Gaia across the river.","country":"Portugal","region":"Europe","about":"porto"},
{"id":"ci-71","cat":"cities","name":"Qingdao","lat":36.07,"lon":120.38,"note":"A port city in Shandong, about 10 million. Tsingtao beer, brewed since the German concession of 1903, the world's largest iron ore import port, and Munich's natural sister city.","country":"China","region":"Asia","about":"qingdao"},
{"id":"ci-72","cat":"cities","name":"Chongqing","lat":29.56,"lon":106.55,"note":"A municipality on the Yangtze in south-west China, about 32 million in the whole area. The world's largest laptop maker and a river port 2,000 km from the sea.","country":"China","region":"Asia","about":"chongqing"},
{"id":"ci-73","cat":"cities","name":"Harbin","lat":45.8,"lon":126.53,"note":"The capital of Heilongjiang in China's far north-east, about 10 million, with Russian architecture and an ice festival. Soybeans and the Daqing oilfield are nearby.","country":"China","region":"Asia","about":"harbin"},
{"id":"ci-74","cat":"cities","name":"Osaka","lat":34.69,"lon":135.5,"note":"Japan's second city on the Inland Sea, about 19 million in the Keihanshin area. The Dōjima rice exchange here invented futures trading in the 1700s.","country":"Japan","region":"Asia","about":"osaka"},
{"id":"ci-75","cat":"cities","name":"Busan","lat":35.18,"lon":129.08,"note":"South Korea's second city and largest port, about 3.4 million. The world's seventh container port, and the shipyards of the country that builds most of the world's LNG carriers.","country":"South Korea","region":"Asia","about":"busan"},
{"id":"ci-76","cat":"cities","name":"Taipei","lat":25.03,"lon":121.57,"note":"Taiwan's capital, about 7 million in the metro area. TSMC's chips, made in Hsinchu an hour away, are the world's most important export.","country":"Taiwan","region":"Asia","about":"taipei"},
{"id":"ci-77","cat":"cities","name":"Sydney","lat":-33.87,"lon":151.21,"note":"Australia's largest city on its harbour, about 5.3 million. The ASX, the big miners' listings, and the Hunter Valley's coal and wine to the north.","country":"Australia","region":"Oceania","about":"sydney"},
{"id":"ci-78","cat":"cities","name":"Melbourne","lat":-37.81,"lon":144.96,"note":"Victoria's capital on Port Phillip Bay, about 5.2 million. BHP and Rio Tinto are headquartered here; Australia's cultural capital by its own account.","country":"Australia","region":"Oceania","about":"melbourne"},
{"id":"ci-79","cat":"cities","name":"Brasília","lat":-15.79,"lon":-47.88,"note":"Brazil's capital, built from nothing in 1960 on the central plateau, about 3 million. The soybean belt of Mato Grosso lies to the west.","country":"Brazil","region":"South America","about":"brasilia"},
{"id":"ci-80","cat":"cities","name":"São Paulo","lat":-23.55,"lon":-46.63,"note":"Brazil's largest city, about 22 million in the metro area. The B3 exchange, the sugar and coffee trading houses, and the port of Santos down the escarpment.","country":"Brazil","region":"South America","about":"sao-paulo"},
{"id":"ci-81","cat":"cities","name":"Montevideo","lat":-34.9,"lon":-56.16,"note":"Uruguay's capital on the Río de la Plata, about 1.8 million, half the country. Beef, soybeans and pulp are the exports; the river's deep-water port is here.","country":"Uruguay","region":"South America","about":"montevideo"},
{"id":"ci-82","cat":"cities","name":"Havana","lat":23.11,"lon":-82.37,"note":"Cuba's capital, about 2.1 million. Sugar, once the economy, has collapsed; nickel, cigars and rum remain.","country":"Cuba","region":"North America","about":"havana"},
{"id":"ci-83","cat":"cities","name":"Panama City","lat":8.98,"lon":-79.52,"note":"Panama's capital at the Pacific end of the canal, about 1.9 million. The canal's tolls and the ship registry (the world's largest flag) fund a skyline of banks.","country":"Panama","region":"North America","about":"panama-city"},
{"id":"ci-84","cat":"cities","name":"Anchorage","lat":61.22,"lon":-149.9,"note":"Alaska's largest city, about 290,000. The crude from Prudhoe Bay runs 1,300 km by pipeline to Valdez; the airport is a cargo hub between Asia and America.","country":"the United States","region":"North America","about":"anchorage"},
{"id":"ci-85","cat":"cities","name":"Honolulu","lat":21.31,"lon":-157.86,"note":"Hawaii's capital on Oahu, about 1 million. The mid-Pacific crossroads: Pearl Harbor, and a refinery that runs on imported crude.","country":"the United States","region":"North America","about":"honolulu"},
{"id":"ci-86","cat":"cities","name":"Denver","lat":39.74,"lon":-104.99,"note":"Colorado's capital at 1,600 m, the Mile High City, about 3 million in the metro area. The gateway to the Rockies' oil, gas and coal basins.","country":"the United States","region":"North America","about":"denver"},
{"id":"ci-87","cat":"cities","name":"Chicago","lat":41.88,"lon":-87.63,"note":"America's third city on Lake Michigan, about 9.5 million. The CME and CBOT: the world's grain, livestock and interest-rate futures are priced here.","country":"the United States","region":"North America","about":"chicago"},
{"id":"ci-88","cat":"cities","name":"Toronto","lat":43.65,"lon":-79.38,"note":"Canada's largest city on Lake Ontario, about 6.7 million. The TSX lists more mining companies than any other exchange; the banks and the Bay Street traders.","country":"Canada","region":"North America","about":"toronto"},
{"id":"ci-89","cat":"cities","name":"Montreal","lat":45.5,"lon":-73.57,"note":"Quebec's largest city on the St Lawrence, about 4.3 million, French-speaking. The port where the Seaway's grain ships meet the ocean; aluminium smelted on Quebec hydropower.","country":"Canada","region":"North America","about":"montreal"},
{"id":"ci-90","cat":"cities","name":"Miami","lat":25.76,"lon":-80.19,"note":"Florida's largest metro area, about 6.3 million, the business capital of Latin America in the United States. Cruise ships, banking and the Everglades' sugar cane.","country":"the United States","region":"North America","about":"miami"},
{"id":"ci-91","cat":"cities","name":"Yerevan","lat":40.18,"lon":44.51,"note":"Armenia's capital below Mount Ararat, about 1.1 million. Copper and molybdenum from Zangezur, and brandy.","country":"Armenia","region":"Asia","about":"yerevan"},
{"id":"ci-92","cat":"cities","name":"Tashkent","lat":41.3,"lon":69.24,"note":"Uzbekistan's capital, about 3 million, Central Asia's largest city. Cotton, gold (Muruntau is the world's largest open-pit gold mine) and gas.","country":"Uzbekistan","region":"Asia","about":"tashkent"},
{"id":"ci-93","cat":"cities","name":"Kabul","lat":34.53,"lon":69.17,"note":"Afghanistan's capital at 1,800 m, about 4.5 million. Lithium and copper deposits the world argues over, and little infrastructure to mine them.","country":"Afghanistan","region":"Asia","about":"kabul"},
{"id":"ci-94","cat":"cities","name":"Muscat","lat":23.59,"lon":58.41,"note":"Oman's capital on the Gulf of Oman, about 1.5 million. Outside the Strait of Hormuz, which is why Oman's exports don't need to pass it; Duqm's refinery is down the coast.","country":"Oman","region":"Asia","about":"muscat"},
{"id":"ci-95","cat":"cities","name":"Sanaa","lat":15.37,"lon":44.19,"note":"Yemen's capital at 2,300 m, about 3 million, with a walled old city. The country's coffee gave the world the word mocha, after the port of Mokha.","country":"Yemen","region":"Asia","about":"sanaa"},
{"id":"ci-96","cat":"cities","name":"Amman","lat":31.95,"lon":35.93,"note":"Jordan's capital, about 4 million. Phosphate and potash from the Dead Sea are the exports; the port is Aqaba on the Red Sea.","country":"Jordan","region":"Asia","about":"amman"},
{"id":"ci-97","cat":"cities","name":"Beirut","lat":33.89,"lon":35.5,"note":"Lebanon's capital on the Mediterranean, about 2.4 million. Once the Middle East's banking centre; the port blew up in 2020. The Bekaa Valley's vineyards are an hour inland.","country":"Lebanon","region":"Asia","about":"beirut"},
{"id":"ci-98","cat":"cities","name":"Dakar","lat":14.72,"lon":-17.47,"note":"Senegal's capital on the Cape Verde peninsula, the westernmost point of mainland Africa, about 4 million. Peanuts, phosphates, fish, and new offshore oil and gas.","country":"Senegal","region":"Africa","about":"dakar"},
{"id":"ci-99","cat":"cities","name":"Abidjan","lat":5.36,"lon":-4.01,"note":"Côte d'Ivoire's economic capital on the lagoon, about 6 million. The world's largest cocoa producer ships its beans from here and from San Pedro.","country":"Côte d'Ivoire","region":"Africa","about":"abidjan"},
{"id":"ci-100","cat":"cities","name":"Kampala","lat":0.35,"lon":32.58,"note":"Uganda's capital on hills above Lake Victoria, about 4 million. Coffee (robusta) and the Lake Albert oilfields, with a pipeline to Tanzania under construction.","country":"Uganda","region":"Africa","about":"kampala"},
{"id":"ci-101","cat":"cities","name":"Dar es Salaam","lat":-6.79,"lon":39.28,"note":"Tanzania's largest city and port, about 7 million. The port serves Zambia's copper and the Congo's cobalt; Zanzibar is across the water.","country":"Tanzania","region":"Africa","about":"dar-es-salaam"},
{"id":"ci-102","cat":"cities","name":"Maputo","lat":-25.97,"lon":32.58,"note":"Mozambique's capital on Delagoa Bay, about 1.1 million. The port for South Africa's coal and chrome, and the base for the Rovuma LNG projects far to the north.","country":"Mozambique","region":"Africa","about":"maputo"},
{"id":"ci-103","cat":"cities","name":"Antananarivo","lat":-18.88,"lon":47.51,"note":"Madagascar's capital in the highlands, about 3.7 million. Vanilla, where Madagascar grows most of the world's, and nickel from Ambatovy.","country":"Madagascar","region":"Africa","about":"antananarivo"},
{"id":"ci-104","cat":"cities","name":"Windhoek","lat":-22.56,"lon":17.08,"note":"Namibia's capital, about 500,000, in the central highlands. Uranium (Rössing, Husab), diamonds from the seabed, and the 2022 offshore oil finds.","country":"Namibia","region":"Africa","about":"windhoek"},
{"id":"ci-105","cat":"cities","name":"Quito","lat":-0.18,"lon":-78.47,"note":"Ecuador's capital at 2,850 m, on the equator, about 2 million. Bananas (the world's largest exporter), shrimp, cocoa and oil from the Amazon.","country":"Ecuador","region":"South America","about":"quito"},
{"id":"ci-106","cat":"cities","name":"La Paz","lat":-16.5,"lon":-68.15,"note":"Bolivia's seat of government at 3,640 m, the highest in the world, about 2 million with El Alto. Lithium in the Salar de Uyuni, silver from Potosí since 1545.","country":"Fiji","region":"Oceania","about":"la-paz"},
{"id":"ci-107","cat":"cities","name":"Asunción","lat":-25.26,"lon":-57.58,"note":"Paraguay's capital on the Paraguay River, about 3 million. Soybeans and beef barged down the river; the Itaipú dam's electricity is the other export.","country":"Paraguay","region":"South America","about":"asuncion"},
{"id":"tr-01","cat":"trade","name":"The port of Rotterdam","lat":51.95,"lon":4.14,"note":"Europe's largest port, on the Rhine delta, about 440 million tonnes a year: crude for the Pernis refinery, the ARA oil products hub, container terminals at Maasvlakte, and the Rhine barge trade into Germany.","country":"the Netherlands","region":"Europe","about":"the-port-of-rotterdam"},
{"id":"tr-02","cat":"trade","name":"The port of Antwerp","lat":51.27,"lon":4.4,"note":"Europe's second port, on the Scheldt, and the largest chemical cluster outside Houston: BASF, Total's refinery, Ineos, and the middle letter of ARA.","country":"Belgium","region":"Europe","about":"the-port-of-antwerp"},
{"id":"tr-03","cat":"trade","name":"Fujairah","lat":25.12,"lon":56.34,"note":"The UAE's port on the Gulf of Oman, outside the Strait of Hormuz: the world's second bunkering hub, a tank farm for the Gulf's products, and the end of the Habshan pipeline that bypasses the strait.","country":"the United Arab Emirates","region":"Asia","about":"fujairah"},
{"id":"tr-04","cat":"trade","name":"Ras Tanura","lat":26.64,"lon":50.16,"note":"Saudi Aramco's main crude export terminal on the Gulf, with the kingdom's oldest refinery (1945). Most of the world's largest oil exporter's crude leaves from here and from Ju'aymah next door.","country":"Saudi Arabia","region":"Asia","about":"ras-tanura"},
{"id":"tr-05","cat":"trade","name":"Kharg Island","lat":29.23,"lon":50.32,"note":"Iran's main oil export terminal, an island 25 km off the coast in the northern Gulf, handling around 90% of its crude exports. The target in every war since 1980.","country":"Iran","region":"Asia","about":"kharg-island"},
{"id":"tr-06","cat":"trade","name":"Ras Laffan","lat":25.91,"lon":51.55,"note":"Qatar's LNG complex on the north coast: 14 liquefaction trains, 77 million tonnes a year and rising to 126, the largest LNG export site in the world.","country":"Qatar","region":"Asia","about":"ras-laffan"},
{"id":"tr-07","cat":"trade","name":"The Jamnagar refinery","lat":22.35,"lon":69.85,"note":"Reliance's complex in Gujarat, the world's largest refinery at about 1.24 million barrels a day, a deep-conversion site that exports products to Europe and buys Russian crude at a discount.","country":"India","region":"Asia","about":"the-jamnagar-refinery"},
{"id":"tr-08","cat":"trade","name":"Jurong Island","lat":1.27,"lon":103.7,"note":"Singapore's refining and petrochemical island, reclaimed from seven islets: ExxonMobil's and Shell's refineries, and the storage behind the world's biggest bunkering port.","country":"Singapore","region":"Asia","about":"jurong-island"},
{"id":"tr-09","cat":"trade","name":"Port Hedland","lat":-20.31,"lon":118.58,"note":"Western Australia's iron ore port in the Pilbara, the world's largest bulk port by tonnage, about 550 million tonnes a year, almost all of it to China.","country":"Australia","region":"Oceania","about":"port-hedland"},
{"id":"tr-10","cat":"trade","name":"The port of Newcastle, Australia","lat":-32.93,"lon":151.78,"note":"On the Hunter River in New South Wales, the world's largest coal export port, about 150 million tonnes a year of thermal coal to Japan, Korea, Taiwan and China.","country":"Australia","region":"Oceania","about":"the-port-of-newcastle-australia"},
{"id":"tr-11","cat":"trade","name":"The port of Santos","lat":-23.96,"lon":-46.33,"note":"Brazil's largest port on the coast below São Paulo: the world's biggest sugar export port, plus soybeans, coffee, corn and containers.","country":"Brazil","region":"South America","about":"the-port-of-santos"},
{"id":"tr-12","cat":"trade","name":"The Houston Ship Channel","lat":29.73,"lon":-95.08,"note":"A 80-km dredged channel from Houston to the Gulf of Mexico, lined by the largest refining and petrochemical complex in the US: ExxonMobil Baytown, the Deer Park refinery, and the export docks.","country":"the United States","region":"North America","about":"the-houston-ship-channel"},
{"id":"tr-13","cat":"trade","name":"Cushing, Oklahoma","lat":35.98,"lon":-96.77,"note":"A town of 8,000 that is the delivery point for WTI futures, with about 90 million barrels of tank farms where the pipelines meet. 'The pipeline crossroads of the world' sets the US benchmark.","country":"the United States","region":"North America","about":"cushing-oklahoma"},
{"id":"tr-14","cat":"trade","name":"Primorsk","lat":60.35,"lon":28.6,"note":"Russia's largest oil export port, on the Gulf of Finland west of St Petersburg: the end of the Baltic Pipeline System, loading Urals crude for Europe and, since 2022, for India and China.","country":"Russia","region":"Europe","about":"primorsk"},
{"id":"tr-15","cat":"trade","name":"Novorossiysk","lat":44.72,"lon":37.77,"note":"Russia's main Black Sea port, exporting Urals crude, grain and the Caspian Pipeline Consortium's Kazakh crude from the terminal next door.","country":"Russia","region":"Europe","about":"novorossiysk"},
{"id":"tr-16","cat":"trade","name":"The Ceyhan terminal","lat":36.87,"lon":35.93,"note":"On Turkey's Mediterranean coast, the end of the Baku–Tbilisi–Ceyhan pipeline from Azerbaijan and of the Kirkuk–Ceyhan line from Iraq: Caspian and Kurdish crude reach the sea here.","country":"Turkey","region":"Asia","about":"the-ceyhan-terminal"},
{"id":"tr-17","cat":"trade","name":"Sabine Pass","lat":29.74,"lon":-93.87,"note":"On the Texas–Louisiana border, Cheniere's terminal: the first US LNG export plant, in 2016, now one of the largest in the world with six trains.","country":"the United States","region":"North America","about":"sabine-pass"},
{"id":"tr-18","cat":"trade","name":"Barrow Island (Gorgon LNG)","lat":-20.8,"lon":115.4,"note":"Off Western Australia's Pilbara coast, Chevron's Gorgon project: 15.6 million tonnes a year of LNG and the world's largest carbon capture and storage scheme, on a nature reserve.","country":"Australia","region":"Oceania","about":"barrow-island-gorgon-lng"},
{"id":"tr-19","cat":"trade","name":"The Escondida mine","lat":-24.27,"lon":-69.07,"note":"In Chile's Atacama Desert at 3,000 m, operated by BHP: the world's largest copper mine, over a million tonnes a year, more than 5% of world supply.","country":"Chile","region":"South America","about":"the-escondida-mine"},
{"id":"tr-20","cat":"trade","name":"Chuquicamata","lat":-22.31,"lon":-68.9,"note":"Codelco's open-pit copper mine near Calama in northern Chile, one of the largest holes dug by man, about 4 km across and a kilometre deep, now going underground.","country":"Chile","region":"South America","about":"chuquicamata"},
{"id":"tr-21","cat":"trade","name":"The Grasberg mine","lat":-4.05,"lon":137.11,"note":"In the highlands of Papua, Indonesia, at 4,000 m, Freeport's mine: the world's largest gold mine and second copper mine, now mined underground.","country":"Indonesia","region":"Asia","about":"the-grasberg-mine"},
{"id":"tr-22","cat":"trade","name":"Oyu Tolgoi","lat":43,"lon":106.85,"note":"Rio Tinto's copper and gold mine in the Gobi Desert, 80 km from the Chinese border, one of the largest copper deposits found this century; its underground mine opened in 2023.","country":"Mongolia","region":"Asia","about":"oyu-tolgoi"},
{"id":"tr-23","cat":"trade","name":"Olympic Dam","lat":-30.44,"lon":136.88,"note":"BHP's mine in South Australia: the world's largest known uranium deposit and a major copper mine, with gold and silver, 560 km north of Adelaide.","country":"Australia","region":"Oceania","about":"olympic-dam"},
{"id":"tr-24","cat":"trade","name":"Carajás","lat":-6.07,"lon":-50.17,"note":"Vale's mine in the Brazilian state of Pará, the world's largest iron ore mine, with the highest-grade ore anywhere, railed 900 km to the port at São Luís.","country":"Brazil","region":"South America","about":"carajas"},
{"id":"tr-25","cat":"trade","name":"Norilsk","lat":69.35,"lon":88.2,"note":"A closed city in Siberia above the Arctic Circle, the world's largest nickel and palladium producer, Nornickel's base and one of the most polluted places on Earth.","country":"Russia","region":"Asia","about":"norilsk"},
{"id":"tr-26","cat":"trade","name":"Kiruna","lat":67.86,"lon":20.22,"note":"Sweden's iron ore mine in Lapland, LKAB's, the largest underground iron mine in the world; the town is being moved 3 km because the mine is undermining it.","country":"Sweden","region":"Europe","about":"kiruna"},
{"id":"tr-27","cat":"trade","name":"Sudbury","lat":46.49,"lon":-81,"note":"A city in Ontario on a 1.8-billion-year-old meteorite crater, the world's largest source of nickel for a century, mined by Vale and Glencore.","country":"Canada","region":"North America","about":"sudbury"},
{"id":"tr-28","cat":"trade","name":"The Daqing oilfield","lat":46.59,"lon":125,"note":"China's largest oilfield, in Heilongjiang, found in 1959 and the symbol of Maoist industry; still producing after 60 years, but a fraction of its peak.","country":"China","region":"Asia","about":"the-daqing-oilfield"},
{"id":"tr-29","cat":"trade","name":"The Ghawar oilfield","lat":25.43,"lon":49.62,"note":"In Saudi Arabia's Eastern Province, the world's largest conventional oilfield, 280 km long, producing since 1951; it has made more oil than any other field, about 3.8 million barrels a day at its peak.","country":"Saudi Arabia","region":"Asia","about":"the-ghawar-oilfield"},
{"id":"tr-30","cat":"trade","name":"West Qurna","lat":30.65,"lon":47.37,"note":"A giant field near Basra in southern Iraq, developed by ExxonMobil and Lukoil, with reserves of 43 billion barrels across its two phases, one of the largest fields in the world.","country":"Iraq","region":"Asia","about":"west-qurna"},
{"id":"tr-31","cat":"trade","name":"Tengiz","lat":46.15,"lon":53.33,"note":"Kazakhstan's giant field on the north-east Caspian shore, operated by Chevron since 1993: deep, high-pressure, sour crude, exported through the CPC pipeline to Novorossiysk.","country":"Kazakhstan","region":"Asia","about":"tengiz"},
{"id":"tr-32","cat":"trade","name":"Prudhoe Bay","lat":70.33,"lon":-148.7,"note":"On Alaska's North Slope, the largest oilfield in North America, found in 1968; its crude runs 1,300 km down the Trans-Alaska Pipeline to Valdez.","country":"the United States","region":"North America","about":"prudhoe-bay"},
{"id":"tr-33","cat":"trade","name":"Midland, Texas","lat":31.99,"lon":-102.08,"note":"The capital of the Permian Basin, the most productive oil basin in the world since the shale boom, about 6 million barrels a day; the Midland–Houston price spread is a market of its own.","country":"the United States","region":"North America","about":"midland-texas"},
{"id":"tr-34","cat":"trade","name":"Williston, North Dakota","lat":48.15,"lon":-103.62,"note":"The boom town of the Bakken shale, which made North Dakota the second oil-producing state; the crude once left by rail, now by pipeline.","country":"the United States","region":"North America","about":"williston-north-dakota"},
{"id":"tr-35","cat":"trade","name":"Fort McMurray","lat":56.73,"lon":-111.38,"note":"The town at the centre of the Athabasca oil sands in Alberta, the world's third-largest oil reserve: mined and steamed bitumen, upgraded or diluted for pipelines south.","country":"Canada","region":"North America","about":"fort-mcmurray"},
{"id":"tr-36","cat":"trade","name":"The Suez Canal","lat":30.45,"lon":32.35,"note":"The 193-km sea-level canal between the Mediterranean and the Red Sea, opened in 1869: about 12% of world trade and 8% of LNG, until the Houthi attacks of 2024 sent ships round the Cape.","country":"Egypt","region":"Africa","about":"suez-canal"},
{"id":"tr-37","cat":"trade","name":"The Panama Canal","lat":9.08,"lon":-79.68,"note":"The 82-km canal across the isthmus, opened in 1914 and widened in 2016 for larger ships: 5% of world trade, and LNG and LPG from the US Gulf to Asia, when the lakes have enough water.","country":"Panama","region":"North America","about":"panama-canal"},
{"id":"tr-38","cat":"trade","name":"The Strait of Hormuz","lat":26.57,"lon":56.25,"note":"The strait between Iran and Oman, 33 km wide at its narrowest, through which about a fifth of the world's oil and a quarter of its LNG pass: the most important chokepoint on Earth.","country":"Iran and Oman","region":"Asia","about":"strait-of-hormuz"},
{"id":"tr-39","cat":"trade","name":"The Strait of Malacca","lat":2.5,"lon":101.5,"note":"Between the Malay Peninsula and Sumatra, 2.8 km wide at its narrowest, the shortest route from the Indian Ocean to China and Japan: a quarter of world trade and most of East Asia's oil.","country":"Malaysia and Indonesia","region":"Asia","about":"strait-of-malacca"},
{"id":"tr-40","cat":"trade","name":"Bab-el-Mandeb","lat":12.58,"lon":43.33,"note":"The 'Gate of Tears', 30 km wide between Yemen and Djibouti, the southern entrance to the Red Sea and the Suez route: every tanker between the Gulf and Europe passes it.","country":"Yemen and Djibouti","region":"Asia","about":"bab-el-mandeb"},
{"id":"tr-41","cat":"trade","name":"The Bosporus","lat":41.12,"lon":29.05,"note":"The strait through Istanbul connecting the Black Sea to the Marmara and the Mediterranean, 700 m wide at its narrowest: the only way out for Russian, Kazakh and Ukrainian exports.","country":"Turkey","region":"Europe","about":"the-bosporus"},
{"id":"tr-42","cat":"trade","name":"The Strait of Gibraltar","lat":35.95,"lon":-5.6,"note":"The 14-km strait between Spain and Morocco, the entrance to the Mediterranean; Algeciras on the Spanish side is a major bunkering and container port.","country":"Spain and Morocco","region":"Africa","about":"the-strait-of-gibraltar"},
{"id":"tr-43","cat":"trade","name":"The Cape of Good Hope","lat":-34.36,"lon":18.47,"note":"The headland at the south-western tip of Africa; the route around it is what tankers take when the Suez Canal is closed, adding two weeks to Asia–Europe voyages.","country":"South Africa","region":"Africa","about":"the-cape-of-good-hope"},
{"id":"tr-44","cat":"trade","name":"The Øresund","lat":55.9,"lon":12.7,"note":"The strait between Copenhagen and Malmö, the main passage from the Baltic to the North Sea: Russian Baltic crude and the Baltic states' trade pass under its bridge.","country":"Denmark and Sweden","region":"Europe","about":"the-resund"},
{"id":"tr-45","cat":"trade","name":"Jubail","lat":27,"lon":49.66,"note":"Saudi Arabia's industrial city on the Gulf, built from the 1970s: SABIC's petrochemicals, the SATORP and SAMREF refineries, and the world's largest industrial complex.","country":"Saudi Arabia","region":"Asia","about":"jubail"},
{"id":"tr-46","cat":"trade","name":"Yanbu","lat":24.09,"lon":38.06,"note":"Saudi Arabia's Red Sea industrial port, the end of the 1,200-km East–West pipeline that carries crude across the kingdom to bypass Hormuz; refineries and a petrochemical complex.","country":"Saudi Arabia","region":"Asia","about":"yanbu"},
{"id":"tr-47","cat":"trade","name":"Mombasa","lat":-4.05,"lon":39.67,"note":"Kenya's port on the Indian Ocean, the gateway for Uganda, Rwanda and eastern Congo, importing their fuel and exporting their coffee and tea.","country":"Kenya","region":"Africa","about":"mombasa"},
{"id":"tr-48","cat":"trade","name":"Durban","lat":-29.87,"lon":31.03,"note":"South Africa's largest port and the busiest in sub-Saharan Africa, on the Indian Ocean; it handles the country's container trade and its crude imports for the Sapref refinery.","country":"South Africa","region":"Africa","about":"durban"},
{"id":"tr-49","cat":"trade","name":"Richards Bay","lat":-28.8,"lon":32.08,"note":"South Africa's coal export port on the Indian Ocean, the largest coal terminal in Africa, about 70 million tonnes a year, mostly to India and Asia.","country":"South Africa","region":"Africa","about":"richards-bay"},
{"id":"tr-50","cat":"trade","name":"Dalian","lat":38.91,"lon":121.62,"note":"A port city in Liaoning on the Bohai Sea, north-east China's oil port and refining centre, with the Dalian Commodity Exchange's iron ore, soybean and coal futures.","country":"China","region":"Asia","about":"dalian"},
{"id":"tr-51","cat":"trade","name":"Ningbo-Zhoushan","lat":29.87,"lon":121.55,"note":"The world's busiest port by cargo tonnage, on Hangzhou Bay south of Shanghai: crude, iron ore and containers, and the Zhoushan oil storage and bunkering hub.","country":"China","region":"Asia","about":"ningbo-zhoushan"},
{"id":"tr-52","cat":"trade","name":"Tianjin","lat":38.98,"lon":117.73,"note":"Northern China's largest port, on the Bohai Sea, the gateway to Beijing: containers, crude and the Binhai industrial zone.","country":"China","region":"Asia","about":"tianjin"},
{"id":"tr-53","cat":"trade","name":"Colombo","lat":6.93,"lon":79.85,"note":"Sri Lanka's capital and port, a transhipment hub between the Middle East and East Asia, with India's container cargo passing through; tea is the country's export.","country":"Sri Lanka","region":"Asia","about":"colombo"},
{"id":"tr-54","cat":"trade","name":"Chittagong","lat":22.33,"lon":91.8,"note":"Bangladesh's main port on the Bay of Bengal, handling 90% of the country's trade, including the garment exports and the fuel imports.","country":"Bangladesh","region":"Asia","about":"chittagong"},
{"id":"tr-55","cat":"trade","name":"Kaohsiung","lat":22.62,"lon":120.27,"note":"Taiwan's largest port and industrial city in the south, with the island's refineries and petrochemical plants and one of the world's top container ports.","country":"Taiwan","region":"Asia","about":"kaohsiung"},
{"id":"tr-56","cat":"trade","name":"Long Beach","lat":33.77,"lon":-118.19,"note":"The port beside Los Angeles, which together with LA's is the largest container complex in the Americas: the gateway for Asian imports into the United States.","country":"the United States","region":"North America","about":"long-beach"},
{"id":"tr-57","cat":"trade","name":"Corpus Christi","lat":27.8,"lon":-97.4,"note":"A Texas Gulf port that became the largest US crude export port after the 2015 lifting of the export ban, shipping Permian crude to Europe and Asia.","country":"the United States","region":"North America","about":"corpus-christi"},
{"id":"tr-58","cat":"trade","name":"Tema","lat":5.63,"lon":0,"note":"Ghana's main port, east of Accra, sitting on the Greenwich meridian: cocoa, manganese, bauxite and the country's fuel imports.","country":"Ghana","region":"Africa","about":"tema"},
{"id":"tr-59","cat":"trade","name":"Walvis Bay","lat":-22.96,"lon":14.51,"note":"Namibia's deep-water port on the Atlantic, the only one on the coast between Angola and South Africa, serving Botswana and Zambia's copper too.","country":"Namibia","region":"Africa","about":"walvis-bay"},
{"id":"tr-60","cat":"trade","name":"Milford Haven","lat":51.71,"lon":-5.04,"note":"A natural harbour in west Wales, among the deepest in the world: the Valero refinery and two LNG terminals that bring in a fifth of Britain's gas.","country":"the United Kingdom","region":"Europe","about":"milford-haven"},
{"id":"tr-61","cat":"trade","name":"Mongstad","lat":60.81,"lon":5.03,"note":"Norway's largest refinery, Equinor's, on the coast north of Bergen; also a crude terminal and a test centre for carbon capture.","country":"Norway","region":"Europe","about":"mongstad"},
{"id":"tr-62","cat":"trade","name":"Le Havre","lat":49.49,"lon":0.11,"note":"France's largest container port at the mouth of the Seine, with the refineries and oil terminals that feed Paris up the river.","country":"France","region":"Europe","about":"le-havre"},
{"id":"tr-63","cat":"trade","name":"Fos-sur-Mer","lat":43.43,"lon":4.94,"note":"The industrial port west of Marseille, France's largest oil port, with refineries, an LNG terminal and the pipelines to Lyon, Switzerland and Germany.","country":"France","region":"Europe","about":"fos-sur-mer"},
{"id":"tr-64","cat":"trade","name":"Trieste","lat":45.65,"lon":13.78,"note":"Italy's port at the head of the Adriatic, the largest oil port in the Mediterranean: the Transalpine pipeline starts here and supplies refineries in Austria, Bavaria and the Czech Republic.","country":"Italy","region":"Europe","about":"trieste"},
{"id":"tr-65","cat":"trade","name":"Augusta, Sicily","lat":37.23,"lon":15.22,"note":"The refining hub of eastern Sicily, with Sonatrach's and Isab's refineries, a major Mediterranean products supplier and once a Russian-owned one.","country":"Italy","region":"Europe","about":"augusta-sicily"},
{"id":"tr-66","cat":"trade","name":"Sines","lat":37.96,"lon":-8.87,"note":"Portugal's deep-water port on the Atlantic south of Lisbon: the Galp refinery, an LNG terminal, and the landing point for transatlantic cables; Vasco da Gama's birthplace.","country":"Portugal","region":"Europe","about":"sines"},
{"id":"tr-67","cat":"trade","name":"Gdańsk","lat":54.35,"lon":18.65,"note":"Poland's main port on the Baltic, with the Lotos refinery and the Naftoport crude terminal that replaced Russian pipeline oil after 2022; the Solidarity shipyard.","country":"Poland","region":"Europe","about":"gdansk"},
{"id":"tr-68","cat":"trade","name":"Ust-Luga","lat":59.67,"lon":28.4,"note":"Russia's newest Baltic port, west of St Petersburg, built in the 2000s to export coal, crude and oil products that once went through the Baltic states.","country":"Russia","region":"Europe","about":"ust-luga"},
{"id":"tr-69","cat":"trade","name":"The Muuga harbour","lat":59.5,"lon":24.95,"note":"Tallinn's cargo port, east of the city: once a major transit terminal for Russian oil products to the West, now handling Estonia's own trade and grain.","country":"Estonia","region":"Europe","about":"the-muuga-harbour"},
{"id":"tr-70","cat":"trade","name":"Sillamäe","lat":59.4,"lon":27.75,"note":"Estonia's easternmost port, a former closed Soviet uranium-processing town, now a free zone with oil and chemical terminals 25 km from the Russian border.","country":"Estonia","region":"Europe","about":"sillamae"},
{"id":"tr-71","cat":"trade","name":"Hazira","lat":21.1,"lon":72.65,"note":"An industrial port in Gujarat near Surat: Shell's LNG terminal, Reliance's petrochemicals and Essar's steel, on India's west coast.","country":"India","region":"Asia","about":"hazira"},
{"id":"tr-72","cat":"trade","name":"Map Ta Phut","lat":12.7,"lon":101.15,"note":"Thailand's industrial port on the Gulf of Thailand: the country's refineries and petrochemical complex, and its LNG import terminal.","country":"Thailand","region":"Asia","about":"map-ta-phut"},
{"id":"tr-73","cat":"trade","name":"Pengerang","lat":1.37,"lon":104.12,"note":"Malaysia's refining and petrochemical complex at the southern tip of the peninsula, opposite Singapore: Petronas's and Aramco's joint refinery and a deep-water oil terminal.","country":"Malaysia","region":"Asia","about":"pengerang"},
{"id":"tr-74","cat":"trade","name":"Bintulu","lat":3.17,"lon":113.03,"note":"Malaysia's LNG port in Sarawak on Borneo, one of the largest LNG export complexes in the world, shipping to Japan, Korea and China since 1983.","country":"Malaysia","region":"Asia","about":"bintulu"},
{"id":"tr-75","cat":"trade","name":"Bonny Island","lat":4.43,"lon":7.17,"note":"In the Niger Delta, Nigeria's LNG terminal with six trains and a seventh under way; Bonny Light crude, the Nigerian benchmark, is named for the loading terminal here.","country":"Nigeria","region":"Africa","about":"bonny-island"},
{"id":"tr-76","cat":"trade","name":"Pointe-Noire","lat":-4.78,"lon":11.86,"note":"The Republic of the Congo's oil port on the Atlantic, the country's economic capital, where Total's and Eni's offshore crude is loaded.","country":"the Republic of the Congo","region":"Africa","about":"pointe-noire"},
{"id":"tr-77","cat":"trade","name":"Escravos","lat":5.58,"lon":5.17,"note":"Chevron's terminal in the western Niger Delta, loading Escravos Light crude and the site of a gas-to-liquids plant.","country":"Nigeria","region":"Africa","about":"escravos"},
{"id":"tr-78","cat":"trade","name":"The Lekki refinery","lat":6.43,"lon":3.52,"note":"The Dangote refinery east of Lagos, 650,000 barrels a day, the largest single-train refinery in the world, started in 2024; it is meant to end Nigeria's fuel imports.","country":"Nigeria","region":"Africa","about":"the-lekki-refinery"},
{"id":"tr-79","cat":"trade","name":"Sakhalin (Prigorodnoye)","lat":46.63,"lon":142.9,"note":"Russia's Pacific LNG plant on Sakhalin Island, Sakhalin-2, shipping to Japan and Korea since 2009; Shell left in 2022 and Gazprom runs it now.","country":"Russia","region":"Asia","about":"sakhalin-prigorodnoye"},
{"id":"tr-80","cat":"trade","name":"Vitória","lat":-20.32,"lon":-40.34,"note":"The capital of Espírito Santo in Brazil, with the Tubarão port: Vale's iron ore pellets and the country's second iron ore export terminal.","country":"Brazil","region":"South America","about":"vitoria"},
{"id":"tr-81","cat":"trade","name":"Paradip","lat":20.32,"lon":86.62,"note":"A bulk port on India's east coast in Odisha: iron ore, coal and the Indian Oil refinery, one of the country's largest.","country":"India","region":"Asia","about":"paradip"},
{"id":"tr-82","cat":"trade","name":"Nhava Sheva","lat":18.95,"lon":72.95,"note":"Jawaharlal Nehru Port across the harbour from Mumbai, India's largest container port, handling about half the country's container trade.","country":"India","region":"Asia","about":"nhava-sheva"},
{"id":"tr-83","cat":"trade","name":"Yokohama","lat":35.44,"lon":139.64,"note":"Japan's second city and the port of Tokyo Bay, opened to foreign trade in 1859: containers, cars, and the refineries and LNG terminals around the bay.","country":"Japan","region":"Asia","about":"yokohama"},
{"id":"tr-84","cat":"trade","name":"Algeciras","lat":36.13,"lon":-5.45,"note":"Spain's port at the Strait of Gibraltar, facing Morocco: one of Europe's largest container ports and a major bunkering station for ships passing the strait.","country":"Spain","region":"Europe","about":"algeciras"},
{"id":"tr-85","cat":"trade","name":"Immingham","lat":53.62,"lon":-0.19,"note":"On the Humber estuary in Lincolnshire, Britain's largest port by tonnage: two refineries next door, coal and biomass for the Drax power station, and the North Sea ferries.","country":"the United Kingdom","region":"Europe","about":"immingham"},
{"id":"wi-01","cat":"wine","name":"Pauillac","lat":45.2,"lon":-0.75,"note":"A commune in the Médoc on the Gironde's left bank, with three of the five First Growths: Lafite, Latour and Mouton Rothschild. Cabernet Sauvignon on gravel.","country":"France","region":"Europe","about":"pauillac"},
{"id":"wi-02","cat":"wine","name":"Saint-Émilion","lat":44.89,"lon":-0.16,"note":"A medieval town on Bordeaux's right bank, Merlot and Cabernet Franc on limestone, with its own classification and the estates Cheval Blanc and Ausone.","country":"France","region":"Europe","about":"saint-emilion"},
{"id":"wi-03","cat":"wine","name":"Beaune","lat":47.03,"lon":4.84,"note":"The wine capital of Burgundy's Côte d'Or, with the Hospices de Beaune charity auction each November and the négociants' cellars under the town.","country":"France","region":"Europe","about":"beaune"},
{"id":"wi-04","cat":"wine","name":"Épernay","lat":49.04,"lon":3.96,"note":"Champagne's second town, on the Marne, with the Avenue de Champagne's houses (Moët & Chandon, Pol Roger, Perrier-Jouët) and 110 km of chalk cellars beneath it.","country":"France","region":"Europe","about":"epernay"},
{"id":"wi-05","cat":"wine","name":"Reims","lat":49.26,"lon":4.03,"note":"The cathedral city where French kings were crowned and the capital of Champagne: Veuve Clicquot, Taittinger, Ruinart, Krug and Pommery have their cellars in its Roman chalk pits.","country":"France","region":"Europe","about":"reims"},
{"id":"wi-06","cat":"wine","name":"Châteauneuf-du-Pape","lat":44.06,"lon":4.83,"note":"A village in the southern Rhône below a papal ruin: Grenache-led blends of up to 13 grapes on round stones (galets), France's first appellation in 1936.","country":"France","region":"Europe","about":"chateauneuf-du-pape"},
{"id":"wi-07","cat":"wine","name":"Sancerre","lat":47.33,"lon":2.84,"note":"A hilltop town on the upper Loire, the home of Sauvignon Blanc on flinty and chalky soils; Pouilly-Fumé faces it across the river.","country":"France","region":"Europe","about":"sancerre"},
{"id":"wi-08","cat":"wine","name":"Chablis","lat":47.82,"lon":3.8,"note":"Burgundy's northern outpost near Auxerre: Chardonnay on Kimmeridgian limestone, oyster-shell soils, in a cool climate that gives the wine its steel.","country":"France","region":"Europe","about":"chablis"},
{"id":"wi-09","cat":"wine","name":"Colmar","lat":48.08,"lon":7.36,"note":"The wine capital of Alsace, a half-timbered town on the Route des Vins: Riesling, Gewürztraminer and Pinot Gris in France's driest region, under the Vosges' rain shadow.","country":"France","region":"Europe","about":"colmar"},
{"id":"wi-10","cat":"wine","name":"Barolo","lat":44.61,"lon":7.94,"note":"A village in Piedmont's Langhe hills south of Alba, giving its name to Italy's most prized red: Nebbiolo, tannic and long-lived, from the crus around it.","country":"Italy","region":"Europe","about":"barolo"},
{"id":"wi-11","cat":"wine","name":"Montalcino","lat":43.06,"lon":11.49,"note":"A Tuscan hill town south of Siena, the home of Brunello di Montalcino: Sangiovese aged for five years, Italy's first DOCG in 1980.","country":"Italy","region":"Europe","about":"montalcino"},
{"id":"wi-12","cat":"wine","name":"Greve in Chianti","lat":43.58,"lon":11.32,"note":"The market town at the heart of Chianti Classico between Florence and Siena: Sangiovese under the black rooster seal.","country":"Italy","region":"Europe","about":"greve-in-chianti"},
{"id":"wi-13","cat":"wine","name":"Negrar di Valpolicella","lat":45.53,"lon":10.94,"note":"A village in the Valpolicella hills north of Verona, where Amarone is made from Corvina grapes dried on racks for months before fermentation.","country":"Italy","region":"Europe","about":"negrar-di-valpolicella"},
{"id":"wi-14","cat":"wine","name":"Randazzo, on Etna","lat":37.88,"lon":14.95,"note":"A black-lava town on the north slope of Etna, Sicily's volcano, where Nerello Mascalese vines grow at up to 1,000 m on old lava flows.","country":"Italy","region":"Europe","about":"randazzo-on-etna"},
{"id":"wi-15","cat":"wine","name":"Haro, in Rioja","lat":42.58,"lon":-2.85,"note":"The wine town of Rioja Alta, with the historic bodegas (López de Heredia, CVNE, Muga) clustered around the railway station since the 1880s: Tempranillo aged in American oak.","country":"Spain","region":"Europe","about":"haro-in-rioja"},
{"id":"wi-16","cat":"wine","name":"Gratallops, in Priorat","lat":41.19,"lon":0.77,"note":"A village in the Priorat hills behind Tarragona, where in the 1980s a handful of growers revived Garnacha and Cariñena on black slate (llicorella) and made Spain's most expensive reds.","country":"Spain","region":"Europe","about":"gratallops-in-priorat"},
{"id":"wi-17","cat":"wine","name":"Jerez","lat":36.69,"lon":-6.14,"note":"Jerez de la Frontera in Andalusia, the city of sherry: Palomino grapes on white albariza chalk, fortified wines aged under flor in solera systems, with Sanlúcar and El Puerto.","country":"Spain","region":"Europe","about":"jerez"},
{"id":"wi-18","cat":"wine","name":"Pinhão, in the Douro","lat":41.19,"lon":-7.55,"note":"A village on the Douro River in the heart of the port vineyards, terraced schist slopes either side of the water, two hours upriver from Porto.","country":"Portugal","region":"Europe","about":"pinhao-in-the-douro"},
{"id":"wi-19","cat":"wine","name":"Bernkastel, on the Mosel","lat":49.92,"lon":7.07,"note":"A medieval town on the Mosel's bends, with the Doctor vineyard above it: Riesling on steep slate, light, sweet and racy.","country":"Germany","region":"Europe","about":"bernkastel-on-the-mosel"},
{"id":"wi-20","cat":"wine","name":"Rüdesheim, in the Rheingau","lat":49.98,"lon":7.92,"note":"A town on the Rhine where the river turns west below Johannisberg: the Rheingau's dry Rieslings and the monastery that invented late harvest in 1775.","country":"Germany","region":"Europe","about":"rudesheim-in-the-rheingau"},
{"id":"wi-21","cat":"wine","name":"Dürnstein, in the Wachau","lat":48.4,"lon":15.52,"note":"A village on the Danube in the Wachau gorge, below the castle where Richard the Lionheart was held: Grüner Veltliner and Riesling on stone terraces.","country":"Austria","region":"Europe","about":"durnstein-in-the-wachau"},
{"id":"wi-22","cat":"wine","name":"Tokaj","lat":48.12,"lon":21.41,"note":"A town in north-east Hungary at the meeting of two rivers, the home of Tokaji Aszú, the botrytised sweet wine of kings, made from Furmint since the 1600s.","country":"Hungary","region":"Europe","about":"tokaj"},
{"id":"wi-23","cat":"wine","name":"Napa","lat":38.3,"lon":-122.3,"note":"The city at the foot of the Napa Valley north of San Francisco: California's most famous wine region, Cabernet Sauvignon that beat Bordeaux in the 1976 Judgment of Paris.","country":"the United States","region":"North America","about":"napa"},
{"id":"wi-24","cat":"wine","name":"Sonoma","lat":38.29,"lon":-122.46,"note":"The town in the Sonoma Valley west of Napa, where California's commercial wine industry began in the 1850s; Pinot Noir and Chardonnay on the cooler coast side.","country":"the United States","region":"North America","about":"sonoma"},
{"id":"wi-25","cat":"wine","name":"McMinnville, in the Willamette Valley","lat":45.21,"lon":-123.2,"note":"A town in Oregon's Willamette Valley, the centre of the state's Pinot Noir, planted from the 1960s in a climate like Burgundy's.","country":"the United States","region":"North America","about":"mcminnville-in-the-willamette-valley"},
{"id":"wi-26","cat":"wine","name":"Geneva, New York, in the Finger Lakes","lat":42.87,"lon":-76.98,"note":"A town on Seneca Lake in upstate New York, the Finger Lakes' wine centre: Riesling on glacial slopes moderated by the deep lakes.","country":"the United States","region":"North America","about":"geneva-new-york-in-the-finger-lakes"},
{"id":"wi-27","cat":"wine","name":"Mendoza","lat":-32.89,"lon":-68.84,"note":"The city at the foot of the Andes in western Argentina, the country's wine capital: Malbec at altitude, irrigated by snowmelt in a desert, 70% of Argentina's wine.","country":"Argentina","region":"South America","about":"mendoza"},
{"id":"wi-28","cat":"wine","name":"Santa Cruz, in Colchagua","lat":-34.63,"lon":-71.35,"note":"A town in the Colchagua Valley south of Santiago, the heart of Chile's red wine country: Carmenère and Cabernet in a dry, warm valley open to the Pacific.","country":"Chile","region":"South America","about":"santa-cruz-in-colchagua"},
{"id":"wi-29","cat":"wine","name":"The Barossa Valley","lat":-34.53,"lon":138.95,"note":"North-east of Adelaide in South Australia, settled by German Lutherans in the 1840s: Shiraz from some of the world's oldest vines, Penfolds and Henschke.","country":"Australia","region":"Oceania","about":"the-barossa-valley"},
{"id":"wi-30","cat":"wine","name":"Margaret River","lat":-33.95,"lon":115.08,"note":"A wine region on the south-west tip of Western Australia between two oceans, planted from 1967: Cabernet and Chardonnay in a maritime climate.","country":"Australia","region":"Oceania","about":"margaret-river"},
{"id":"wi-31","cat":"wine","name":"The Hunter Valley","lat":-32.78,"lon":151.3,"note":"North of Sydney, Australia's oldest wine region, known for aged Semillon and Shiraz; also the heart of New South Wales coal mining.","country":"Australia","region":"Oceania","about":"the-hunter-valley"},
{"id":"wi-32","cat":"wine","name":"Blenheim, in Marlborough","lat":-41.51,"lon":173.95,"note":"The town at the centre of Marlborough at the top of New Zealand's South Island, which since the 1980s has made Sauvignon Blanc the country's defining wine.","country":"New Zealand","region":"Oceania","about":"blenheim-in-marlborough"},
{"id":"wi-33","cat":"wine","name":"Queenstown, in Central Otago","lat":-45.03,"lon":168.66,"note":"The resort town on Lake Wakatipu in New Zealand's South Island, the world's southernmost wine region, Pinot Noir in a continental mountain climate.","country":"New Zealand","region":"Oceania","about":"queenstown-in-central-otago"},
{"id":"wi-34","cat":"wine","name":"Stellenbosch","lat":-33.93,"lon":18.86,"note":"A university town east of Cape Town, the heart of South African wine since the 1680s: Cabernet, Pinotage (bred here in 1925) and Chenin Blanc in the mountains.","country":"South Africa","region":"Africa","about":"stellenbosch"},
{"id":"wi-35","cat":"wine","name":"Franschhoek","lat":-33.91,"lon":19.12,"note":"The 'French corner', a valley beyond Stellenbosch settled by Huguenots in 1688, now a wine and restaurant town below the Drakenstein mountains.","country":"South Africa","region":"Africa","about":"franschhoek"},
{"id":"wi-36","cat":"wine","name":"Lavaux","lat":46.49,"lon":6.72,"note":"The terraced vineyards on the north shore of Lake Geneva between Lausanne and Montreux, a UNESCO site: Chasselas warmed by the sun, the lake's reflection and the stone walls.","country":"Switzerland","region":"Europe","about":"lavaux"},
{"id":"wi-37","cat":"wine","name":"Sion, in Valais","lat":46.23,"lon":7.36,"note":"The capital of the Valais in the upper Rhône valley, Switzerland's largest wine canton, with vines on dry sunny slopes and Europe's highest vineyards.","country":"Switzerland","region":"Europe","about":"sion-in-valais"},
{"id":"wi-38","cat":"wine","name":"Yinchuan, in Ningxia","lat":38.49,"lon":106.23,"note":"The capital of Ningxia in north-central China, at the foot of the Helan Mountains, where China's most serious wine region has been planted since the 2000s; vines are buried each winter.","country":"China","region":"Asia","about":"yinchuan-in-ningxia"},
{"id":"wi-39","cat":"wine","name":"Kōfu, in Yamanashi","lat":35.66,"lon":138.57,"note":"The capital of Yamanashi prefecture west of Tokyo, in the basin below Mount Fuji, the home of Japanese wine: the native Koshu grape.","country":"Japan","region":"Asia","about":"kofu-in-yamanashi"},
{"id":"wi-40","cat":"wine","name":"Cognac","lat":45.7,"lon":-0.33,"note":"A town on the Charente in western France, the centre of the brandy that bears its name: Ugni Blanc distilled twice in copper pot stills and aged in Limousin oak.","country":"France","region":"Europe","about":"cognac"},
{"id":"wi-41","cat":"wine","name":"Arbois, in the Jura","lat":46.9,"lon":5.77,"note":"The wine capital of the Jura mountains east of Burgundy, Pasteur's childhood home: vin jaune, Savagnin aged under a veil of yeast for six years.","country":"France","region":"Europe","about":"arbois-in-the-jura"},
{"id":"wi-42","cat":"wine","name":"Funchal, Madeira","lat":32.65,"lon":-16.91,"note":"The capital of Madeira in the Atlantic, where the fortified wine is heated and oxidised on purpose, a method discovered when casks crossed the tropics; it keeps for centuries.","country":"Portugal","region":"Europe","about":"funchal-madeira"},
{"id":"wi-43","cat":"wine","name":"Santorini","lat":36.39,"lon":25.46,"note":"A volcanic Cycladic island in the Aegean, Assyrtiko vines trained into baskets against the wind on ash soils, some of the oldest in Europe, never touched by phylloxera.","country":"Greece","region":"Europe","about":"santorini"},
{"id":"wi-44","cat":"wine","name":"Zahlé, in the Bekaa Valley","lat":33.85,"lon":35.9,"note":"The largest town of Lebanon's Bekaa Valley, the country's wine region since Phoenician times, with Château Ksara and Musar's vineyards nearby.","country":"Lebanon","region":"Asia","about":"zahle-in-the-bekaa-valley"},
{"id":"ar-01","cat":"art","name":"The Louvre","lat":48.861,"lon":2.336,"note":"The world's largest and most visited museum, in a former royal palace on the right bank of the Seine in Paris: the Mona Lisa, the Venus de Milo, 35,000 works on show.","country":"France","region":"Europe","pic":"Mona Lisa","about":"louvre"},
{"id":"ar-02","cat":"art","name":"The Musée d'Orsay","lat":48.86,"lon":2.326,"note":"A former railway station on the Seine's left bank in Paris, holding the world's greatest collection of Impressionism: Monet, Renoir, Degas, Van Gogh, Cézanne.","country":"France","region":"Europe","pic":"Bal du moulin de la Galette","about":"the-musee-d-orsay"},
{"id":"ar-03","cat":"art","name":"The Prado","lat":40.414,"lon":-3.692,"note":"Spain's national museum in Madrid, built on the royal collection: Velázquez's Las Meninas, Goya, Bosch's Garden of Earthly Delights, Titian and Rubens.","country":"Spain","region":"Europe","pic":"Las Meninas","about":"prado"},
{"id":"ar-04","cat":"art","name":"The Reina Sofía, where Guernica hangs","lat":40.408,"lon":-3.694,"note":"Madrid's modern art museum, in a former hospital near Atocha, holding Picasso's Guernica since 1992 along with Dalí and Miró.","country":"Spain","region":"Europe","pic":"Guernica (Picasso)","about":"the-reina-sofia-where-guernica-hangs"},
{"id":"ar-05","cat":"art","name":"The Uffizi","lat":43.768,"lon":11.256,"note":"Florence's great gallery, in the Medici's offices beside the Arno: Botticelli's Birth of Venus and Primavera, Leonardo, Michelangelo, Raphael, Titian.","country":"Italy","region":"Europe","pic":"The Birth of Venus","about":"the-uffizi"},
{"id":"ar-06","cat":"art","name":"The Accademia, where Michelangelo's David stands","lat":43.777,"lon":11.259,"note":"The Galleria dell'Accademia in Florence, where the 5-metre David has stood since 1873, moved from the Piazza della Signoria to save it from the weather.","country":"Italy","region":"Europe","about":"the-accademia-where-michelangelo-s-david-stands"},
{"id":"ar-07","cat":"art","name":"The Sistine Chapel","lat":41.903,"lon":12.454,"note":"The papal chapel in the Vatican, where conclaves elect popes under Michelangelo's ceiling (1508–12) and his Last Judgment on the altar wall.","country":"Italy","region":"Europe","pic":"The Creation of Adam","about":"the-sistine-chapel"},
{"id":"ar-08","cat":"art","name":"The Rijksmuseum, home of The Night Watch","lat":52.36,"lon":4.885,"note":"The Dutch national museum in Amsterdam, holding Rembrandt's Night Watch (1642) at the end of its Gallery of Honour, with Vermeer's Milkmaid and the Golden Age.","country":"the Netherlands","region":"Europe","pic":"The Night Watch","about":"the-rijksmuseum-home-of-the-night-watch"},
{"id":"ar-09","cat":"art","name":"The Van Gogh Museum","lat":52.358,"lon":4.881,"note":"On Amsterdam's Museumplein, the world's largest Van Gogh collection, 200 paintings from the family's holdings: Sunflowers, The Bedroom, the self-portraits.","country":"the Netherlands","region":"Europe","pic":"Sunflowers (Van Gogh series)","about":"the-van-gogh-museum"},
{"id":"ar-10","cat":"art","name":"The Mauritshuis, home of Girl with a Pearl Earring","lat":52.08,"lon":4.314,"note":"A 17th-century mansion in The Hague beside the parliament, with Vermeer's Girl with a Pearl Earring, Rembrandt's Anatomy Lesson and Fabritius's Goldfinch.","country":"the Netherlands","region":"Europe","pic":"Girl with a Pearl Earring","about":"the-mauritshuis-home-of-girl-with-a-pearl-earring"},
{"id":"ar-11","cat":"art","name":"The Hermitage","lat":59.94,"lon":30.314,"note":"The Winter Palace of the tsars in St Petersburg, with three million objects: Rembrandts, Matisse and Picasso collected by Moscow merchants, Catherine the Great's purchases.","country":"Russia","region":"Europe","pic":"Dance (Matisse)","about":"the-hermitage"},
{"id":"ar-12","cat":"art","name":"Tate Modern","lat":51.508,"lon":-0.099,"note":"The converted Bankside power station on the Thames in London, opened in 2000, the world's most visited modern art museum, with the Turbine Hall's installations.","country":"the United Kingdom","region":"Europe","pic":"Marilyn Diptych","about":"tate-modern"},
{"id":"ar-13","cat":"art","name":"The National Gallery, London","lat":51.509,"lon":-0.128,"note":"On Trafalgar Square, the national collection of European painting from 1250 to 1900: Van Eyck's Arnolfini Portrait, Turner, Constable, Van Gogh's Sunflowers.","country":"the United Kingdom","region":"Europe","pic":"The Fighting Temeraire","about":"the-national-gallery-london"},
{"id":"ar-14","cat":"art","name":"The British Museum","lat":51.519,"lon":-0.127,"note":"In Bloomsbury, London, founded in 1753, the first national public museum: the Rosetta Stone, the Parthenon marbles, 8 million objects from every culture.","country":"the United Kingdom","region":"Europe","about":"the-british-museum"},
{"id":"ar-15","cat":"art","name":"MoMA","lat":40.761,"lon":-73.978,"note":"The Museum of Modern Art in midtown Manhattan, founded in 1929: Van Gogh's Starry Night, Picasso's Demoiselles d'Avignon, Warhol's soup cans.","country":"the United States","region":"North America","pic":"The Starry Night","about":"moma"},
{"id":"ar-16","cat":"art","name":"The Metropolitan Museum of Art","lat":40.779,"lon":-73.963,"note":"On Fifth Avenue beside Central Park, America's largest museum, two million works from Egypt to the Impressionists, with the Cloisters uptown for medieval art.","country":"the United States","region":"North America","about":"the-metropolitan-museum-of-art"},
{"id":"ar-17","cat":"art","name":"The Guggenheim Bilbao","lat":43.269,"lon":-2.934,"note":"Frank Gehry's titanium-clad museum on the Nervión in Bilbao, opened in 1997, which turned a declining steel city into a destination: 'the Bilbao effect'.","country":"Spain","region":"Europe","about":"the-guggenheim-bilbao"},
{"id":"ar-18","cat":"art","name":"The Kunsthaus Zürich","lat":47.37,"lon":8.548,"note":"Switzerland's largest art museum, on Heimplatz in Zürich, with the Bührle collection of Impressionists, Giacometti, Munch and Swiss painting; a Chipperfield extension opened in 2021.","country":"Switzerland","region":"Europe","about":"the-kunsthaus-zurich"},
{"id":"ar-19","cat":"art","name":"The Kunstmuseum Basel","lat":47.554,"lon":7.594,"note":"The oldest public art collection in the world, from 1661: Holbein, the Basel Picasso vote of 1967, and a great 20th-century collection in a Rhine city of art fairs.","country":"Switzerland","region":"Europe","pic":"Isle of the Dead (painting)","about":"the-kunstmuseum-basel"},
{"id":"ar-20","cat":"art","name":"The Fondation Beyeler","lat":47.59,"lon":7.65,"note":"Renzo Piano's museum in Riehen outside Basel, holding the dealer Ernst Beyeler's collection: Monet's water lilies, Giacometti, Rothko, Bacon, in a garden.","country":"Switzerland","region":"Europe","about":"the-fondation-beyeler"},
{"id":"ar-21","cat":"art","name":"The Munch Museum, home of The Scream","lat":59.906,"lon":10.756,"note":"The Munch museum on Oslo's waterfront, opened in 2021, holding the artist's bequest: versions of The Scream, Madonna, and 26,000 works.","country":"Norway","region":"Europe","pic":"The Scream","about":"the-munch-museum-home-of-the-scream"},
{"id":"ar-22","cat":"art","name":"The Getty Center","lat":34.078,"lon":-118.474,"note":"Richard Meier's travertine museum on a hill above Los Angeles, built on the oil fortune of J. Paul Getty: Van Gogh's Irises, Old Masters and a research institute.","country":"the United States","region":"North America","about":"the-getty-center"},
{"id":"ar-23","cat":"art","name":"The Art Institute of Chicago","lat":41.88,"lon":-87.624,"note":"On Michigan Avenue beside the lake, with Seurat's Grande Jatte, Hopper's Nighthawks, Grant Wood's American Gothic and the great Impressionist collection.","country":"the United States","region":"North America","pic":"Nighthawks","about":"the-art-institute-of-chicago"},
{"id":"ar-24","cat":"art","name":"The Pergamon Museum","lat":52.521,"lon":13.397,"note":"On Berlin's Museum Island, built around the Pergamon Altar, the Ishtar Gate of Babylon and the Market Gate of Miletus; closed for renovation until the 2030s.","country":"Germany","region":"Europe","about":"the-pergamon-museum"},
{"id":"ar-25","cat":"art","name":"The Kunsthistorisches Museum, Vienna","lat":48.204,"lon":16.362,"note":"The Habsburgs' collection on the Ringstrasse: the world's largest group of Bruegels, Vermeer's Art of Painting, Velázquez's infantas, Cellini's salt cellar.","country":"Austria","region":"Europe","pic":"The Hunters in the Snow","about":"the-kunsthistorisches-museum-vienna"},
{"id":"ar-26","cat":"art","name":"The Belvedere, home of Klimt's The Kiss","lat":48.191,"lon":16.381,"note":"Prince Eugene's baroque palace in Vienna, holding the world's largest Klimt collection, with The Kiss (1908), Schiele and Austrian art.","country":"Austria","region":"Europe","pic":"The Kiss (Klimt)","about":"the-belvedere-home-of-klimt-s-the-kiss"},
{"id":"ar-27","cat":"art","name":"The Picasso Museum, Barcelona","lat":41.385,"lon":2.181,"note":"In five medieval palaces in the Born district, with Picasso's early work from his Barcelona years and the Las Meninas series of 1957.","country":"Spain","region":"Europe","about":"the-picasso-museum-barcelona"},
{"id":"ar-28","cat":"art","name":"The Alte Pinakothek","lat":48.149,"lon":11.57,"note":"Munich's gallery of Old Masters, opened in 1836: Dürer's self-portrait, Rubens, Altdorfer's Battle of Alexander, the Wittelsbach collection.","country":"Germany","region":"Europe","about":"the-alte-pinakothek"},
{"id":"ar-29","cat":"art","name":"The Lascaux cave","lat":45.05,"lon":1.17,"note":"A cave in the Dordogne found by four teenagers in 1940, painted 17,000 years ago with horses, aurochs and stags; closed since 1963 and shown as a replica.","country":"France","region":"Europe","about":"the-lascaux-cave"},
{"id":"ar-30","cat":"art","name":"The Altamira cave","lat":43.38,"lon":-4.12,"note":"A cave in Cantabria, Spain, with bison painted on its ceiling 36,000 to 14,000 years ago, the first cave art recognised as prehistoric, in 1879, after decades of disbelief.","country":"Spain","region":"Europe","about":"the-altamira-cave"},
{"id":"ar-31","cat":"art","name":"Monet's garden at Giverny","lat":49.08,"lon":1.53,"note":"The house and garden in Normandy where Monet lived from 1883 to 1926 and planted the water-lily pond he painted for the last 30 years of his life.","country":"France","region":"Europe","about":"monet-s-garden-at-giverny"},
{"id":"ar-32","cat":"art","name":"Arles, where Van Gogh painted the Sunflowers","lat":43.68,"lon":4.63,"note":"A Roman town on the Rhône in Provence, where Van Gogh spent 1888–89, painted Sunflowers, the Yellow House and the Café Terrace, and cut off part of his ear.","country":"France","region":"Europe","about":"arles-where-van-gogh-painted-the-sunflowers"},
{"id":"ar-33","cat":"art","name":"Guernica, the town","lat":43.31,"lon":-2.68,"note":"The Basque town bombed by the German Condor Legion on 26 April 1937, market day, the first mass aerial bombing of civilians in Europe, which Picasso painted within weeks.","country":"Spain","region":"Europe","about":"guernica-the-town"},
{"id":"ar-34","cat":"art","name":"Mont Sainte-Victoire","lat":43.52,"lon":5.63,"note":"The limestone mountain east of Aix-en-Provence that Cézanne painted more than 60 times from the 1880s, working toward the geometry that led to Cubism.","country":"France","region":"Europe","about":"mont-sainte-victoire"},
{"id":"ar-35","cat":"art","name":"The moai of Easter Island","lat":-27.11,"lon":-109.35,"note":"Nearly 900 stone figures carved by the Rapa Nui between 1250 and 1500 on the most remote inhabited island in the Pacific, 3,500 km off Chile.","country":"Chile","region":"South America","about":"the-moai-of-easter-island"},
{"id":"ar-36","cat":"art","name":"Angkor Wat","lat":13.41,"lon":103.87,"note":"The 12th-century Khmer temple in Cambodia, the largest religious monument in the world, built for Vishnu and later Buddhist, at the heart of a city of a million.","country":"Cambodia","region":"Asia","about":"angkor-wat"},
{"id":"ar-37","cat":"art","name":"Petra","lat":30.33,"lon":35.44,"note":"The Nabataean city in southern Jordan carved into rose-red sandstone, with the Treasury at the end of a narrow gorge, a caravan capital on the incense route.","country":"Jordan","region":"Asia","about":"petra"},
{"id":"ar-38","cat":"art","name":"Abu Simbel","lat":22.34,"lon":31.63,"note":"Two temples of Ramesses II cut into a cliff above the Nile in Nubia, moved 65 m uphill in 1968 to save them from Lake Nasser behind the Aswan dam.","country":"Egypt","region":"Africa","about":"abu-simbel"},
{"id":"ar-39","cat":"art","name":"The Taj Mahal","lat":27.17,"lon":78.04,"note":"The white marble mausoleum at Agra built by Shah Jahan for his wife Mumtaz Mahal between 1632 and 1653, the summit of Mughal architecture.","country":"India","region":"Asia","about":"taj-mahal"},
{"id":"ar-40","cat":"art","name":"The Alhambra","lat":37.18,"lon":-3.59,"note":"The Nasrid palace and fortress above Granada, the last Moorish court in Spain, surrendered in 1492: stucco, tile and water in the Court of the Lions.","country":"Spain","region":"Europe","about":"alhambra"},
{"id":"ar-41","cat":"art","name":"The Sagrada Família","lat":41.4,"lon":2.17,"note":"Gaudí's basilica in Barcelona, begun in 1882 and still being built; its central tower will make it the tallest church in the world.","country":"Spain","region":"Europe","about":"sagrada-familia"},
{"id":"ar-42","cat":"art","name":"Neuschwanstein","lat":47.56,"lon":10.75,"note":"Ludwig II of Bavaria's fairy-tale castle in the Alps near Füssen, built from 1869 and never finished, the model for Disney's castle.","country":"Germany","region":"Europe","about":"neuschwanstein"},
{"id":"ar-43","cat":"art","name":"The Bauhaus at Dessau","lat":51.84,"lon":12.23,"note":"Walter Gropius's 1926 school building in Dessau, Germany, where the Bauhaus taught design, architecture and art until the Nazis closed it in 1932.","country":"Germany","region":"Europe","about":"the-bauhaus-at-dessau"},
{"id":"ar-44","cat":"art","name":"Fallingwater","lat":39.91,"lon":-79.47,"note":"Frank Lloyd Wright's 1937 house built over a waterfall at Bear Run in Pennsylvania, the most famous private house in America.","country":"the United States","region":"North America","about":"fallingwater"},
{"id":"ar-45","cat":"art","name":"The Giardini of the Venice Biennale","lat":45.43,"lon":12.36,"note":"The public gardens at the eastern end of Venice where the Biennale has held its national pavilions since 1895, the world's oldest art exhibition.","country":"Italy","region":"Europe","about":"the-giardini-of-the-venice-biennale"},
{"id":"ar-46","cat":"art","name":"Kassel, home of documenta","lat":51.31,"lon":9.5,"note":"A city in Hesse, Germany, where documenta, the world's most important exhibition of contemporary art, has been held every five years since 1955.","country":"Germany","region":"Europe","about":"kassel-home-of-documenta"},
{"id":"ar-47","cat":"art","name":"The Terracotta Army","lat":34.38,"lon":109.28,"note":"Some 8,000 life-size clay soldiers buried to guard the first emperor Qin Shi Huang, near Xi'an, found by farmers digging a well in 1974.","country":"China","region":"Asia","about":"terracotta-army"},
{"id":"ar-48","cat":"art","name":"Chichén Itzá","lat":20.68,"lon":-88.57,"note":"The Maya city in Yucatán with the stepped pyramid of Kukulcán, where a serpent of shadow descends the stairs at the equinox; it flourished around 600 to 1200.","country":"Mexico","region":"North America","about":"chichen-itza"},
{"id":"ar-49","cat":"art","name":"Machu Picchu","lat":-13.16,"lon":-72.55,"note":"The Inca citadel at 2,430 m on a ridge above the Urubamba in Peru, built around 1450 and abandoned a century later, unknown to the outside world until 1911.","country":"Peru","region":"South America","about":"machu-picchu"},
{"id":"ar-50","cat":"art","name":"The pyramids of Giza","lat":29.98,"lon":31.13,"note":"The three pyramids on the plateau west of Cairo, Khufu's the largest, built around 2560 BC; the only one of the Seven Wonders of the ancient world still standing.","country":"Egypt","region":"Africa","about":"the-pyramids-of-giza"},
{"id":"ar-51","cat":"art","name":"Stonehenge","lat":51.18,"lon":-1.83,"note":"The circle of standing stones on Salisbury Plain in Wiltshire, raised about 2500 BC, its bluestones hauled from Wales, aligned on the midsummer sunrise.","country":"the United Kingdom","region":"Europe","about":"stonehenge"},
{"id":"pe-01","cat":"people","name":"Ajaccio, where Napoleon was born","lat":41.92,"lon":8.74,"note":"Corsica's capital, where Napoleon Bonaparte was born in 1769, the year after France bought the island from Genoa; the family house is a museum.","country":"France","region":"Europe","about":"ajaccio-where-napoleon-was-born"},
{"id":"pe-02","cat":"people","name":"Salzburg, where Mozart was born","lat":47.8,"lon":13.04,"note":"The baroque city on the Salzach in Austria, where Mozart was born in 1756 on Getreidegasse; the salt trade that named it built its wealth.","country":"Austria","region":"Europe","about":"salzburg-where-mozart-was-born"},
{"id":"pe-03","cat":"people","name":"Málaga, where Picasso was born","lat":36.72,"lon":-4.42,"note":"The port city of Andalusia where Picasso was born in 1881; he left at ten and never lived in Spain again after 1934.","country":"Spain","region":"Europe","about":"malaga-where-picasso-was-born"},
{"id":"pe-04","cat":"people","name":"Ulm, where Einstein was born","lat":48.4,"lon":9.99,"note":"A city on the Danube in Baden-Württemberg with the world's tallest church spire, where Einstein was born in 1879; the family moved to Munich within a year.","country":"Germany","region":"Europe","about":"ulm-where-einstein-was-born"},
{"id":"pe-05","cat":"people","name":"Zundert, where Van Gogh was born","lat":51.47,"lon":4.66,"note":"A village in North Brabant near the Belgian border where Van Gogh was born in 1853, the son of the pastor, a year to the day after a stillborn brother of the same name.","country":"the Netherlands","region":"Europe","about":"zundert-where-van-gogh-was-born"},
{"id":"pe-06","cat":"people","name":"Warsaw, where Marie Curie was born","lat":52.23,"lon":21.01,"note":"Poland's capital, where Maria Skłodowska was born in 1867 under Russian rule; she left for the Sorbonne in 1891 and named polonium for her country.","country":"Poland","region":"Europe","about":"warsaw-where-marie-curie-was-born"},
{"id":"pe-07","cat":"people","name":"Blenheim Palace, where Churchill was born","lat":51.84,"lon":-1.36,"note":"The Duke of Marlborough's palace in Oxfordshire, built after the battle of 1704, where Winston Churchill was born in 1874, in a cloakroom, during a ball.","country":"the United Kingdom","region":"Europe","about":"blenheim-palace-where-churchill-was-born"},
{"id":"pe-08","cat":"people","name":"Leiden, where Rembrandt was born","lat":52.16,"lon":4.49,"note":"The Dutch university town where Rembrandt was born in 1606, a miller's son; he left for Amsterdam at 25.","country":"the Netherlands","region":"Europe","about":"leiden-where-rembrandt-was-born"},
{"id":"pe-09","cat":"people","name":"Delft, where Vermeer was born","lat":52.01,"lon":4.36,"note":"The canal town between The Hague and Rotterdam where Vermeer was born in 1632 and painted all his life, including its own View of Delft; also the city of blue-and-white pottery.","country":"the Netherlands","region":"Europe","about":"delft-where-vermeer-was-born"},
{"id":"pe-10","cat":"people","name":"Stratford-upon-Avon, where Shakespeare was born","lat":52.19,"lon":-1.71,"note":"A market town in Warwickshire where Shakespeare was born in 1564 and died in 1616; the half-timbered house on Henley Street still stands.","country":"the United Kingdom","region":"Europe","about":"stratford-upon-avon-where-shakespeare-was-born"},
{"id":"pe-11","cat":"people","name":"Vinci, where Leonardo was born","lat":43.78,"lon":10.92,"note":"A hill town in Tuscany west of Florence where Leonardo was born in 1452, the illegitimate son of a notary, and from which he took his name.","country":"Italy","region":"Europe","about":"vinci-where-leonardo-was-born"},
{"id":"pe-12","cat":"people","name":"Caprese, where Michelangelo was born","lat":43.64,"lon":11.99,"note":"A village in the Tuscan Apennines, now Caprese Michelangelo, where the artist was born in 1475 while his father was its magistrate.","country":"Italy","region":"Europe","about":"caprese-where-michelangelo-was-born"},
{"id":"pe-13","cat":"people","name":"Bonn, where Beethoven was born","lat":50.73,"lon":7.1,"note":"The city on the Rhine, West Germany's capital from 1949 to 1990, where Beethoven was born in 1770; he left for Vienna at 21.","country":"Germany","region":"Europe","about":"bonn-where-beethoven-was-born"},
{"id":"pe-14","cat":"people","name":"Eisenach, where Bach was born","lat":50.98,"lon":10.32,"note":"A town in Thuringia below the Wartburg castle, where Luther translated the Bible and Johann Sebastian Bach was born in 1685.","country":"Germany","region":"Europe","about":"eisenach-where-bach-was-born"},
{"id":"pe-15","cat":"people","name":"Żelazowa Wola, where Chopin was born","lat":52.26,"lon":20.31,"note":"A village west of Warsaw where Chopin was born in 1810 in a manor house on the estate where his French father was a tutor; he left Poland at 20.","country":"Poland","region":"Europe","about":"zelazowa-wola-where-chopin-was-born"},
{"id":"pe-16","cat":"people","name":"Příbor, where Freud was born","lat":49.64,"lon":18.14,"note":"A small town in Moravia, then Freiberg in Austria, where Sigmund Freud was born in 1856; the family moved to Vienna when he was three.","country":"the Czech Republic","region":"Europe","about":"pribor-where-freud-was-born"},
{"id":"pe-17","cat":"people","name":"Smiljan, where Tesla was born","lat":44.57,"lon":15.32,"note":"A village in the Lika region of Croatia, then Austrian, where Nikola Tesla was born in 1856, the son of an Orthodox priest, during a lightning storm by his own account.","country":"Croatia","region":"Europe","about":"smiljan-where-tesla-was-born"},
{"id":"pe-18","cat":"people","name":"Porbandar, where Gandhi was born","lat":21.64,"lon":69.61,"note":"A port on the coast of Gujarat where Gandhi was born in 1869, the son of the state's chief minister.","country":"India","region":"Asia","about":"porbandar-where-gandhi-was-born"},
{"id":"pe-19","cat":"people","name":"Mvezo, where Mandela was born","lat":-31.95,"lon":28.49,"note":"A village on the Mbashe River in the Eastern Cape where Nelson Mandela was born in 1918, the son of a Thembu chief.","country":"South Africa","region":"Africa","about":"mvezo-where-mandela-was-born"},
{"id":"pe-20","cat":"people","name":"Rosario, where Che Guevara was born","lat":-32.95,"lon":-60.64,"note":"Argentina's third city on the Paraná, the country's main grain port, where Ernesto Guevara was born in 1928; also Messi's birthplace.","country":"Argentina","region":"South America","about":"rosario-where-che-guevara-was-born"},
{"id":"pe-21","cat":"people","name":"Genoa, where Columbus was born","lat":44.41,"lon":8.93,"note":"The Ligurian port and medieval maritime republic where Columbus was born in 1451, a weaver's son; Italy's largest port today.","country":"Italy","region":"Europe","about":"genoa-where-columbus-was-born"},
{"id":"pe-22","cat":"people","name":"Sabrosa, where Magellan was born","lat":41.27,"lon":-7.57,"note":"A village in the Douro wine country of northern Portugal where Ferdinand Magellan was born about 1480; he sailed for Spain after Portugal refused him.","country":"Portugal","region":"Europe","about":"sabrosa-where-magellan-was-born"},
{"id":"pe-23","cat":"people","name":"Pella, where Alexander the Great was born","lat":40.76,"lon":22.52,"note":"The capital of ancient Macedon, inland from Thessaloniki, where Alexander was born in 356 BC and was tutored by Aristotle.","country":"Greece","region":"Europe","about":"pella-where-alexander-the-great-was-born"},
{"id":"pe-24","cat":"people","name":"Qufu, where Confucius was born","lat":35.6,"lon":116.99,"note":"A city in Shandong where Confucius was born in 551 BC; his temple, mansion and cemetery, tended by his descendants for 2,500 years, are a UNESCO site.","country":"China","region":"Asia","about":"qufu-where-confucius-was-born"},
{"id":"pe-25","cat":"people","name":"Lumbini, where the Buddha was born","lat":27.47,"lon":83.28,"note":"A pilgrimage site in Nepal's Terai lowlands, where Siddhartha Gautama was born about 563 BC under a sal tree; Ashoka's pillar marks the spot.","country":"Nepal","region":"Asia","about":"lumbini-where-the-buddha-was-born"},
{"id":"pe-26","cat":"people","name":"Trier, where Marx was born","lat":49.75,"lon":6.64,"note":"Germany's oldest city, a Roman capital on the Mosel, where Karl Marx was born in 1818; the house on Brückenstrasse is a museum.","country":"Germany","region":"Europe","about":"trier-where-marx-was-born"},
{"id":"pe-27","cat":"people","name":"Shrewsbury, where Darwin was born","lat":52.71,"lon":-2.75,"note":"The county town of Shropshire in a loop of the Severn, where Charles Darwin was born in 1809.","country":"the United Kingdom","region":"Europe","about":"shrewsbury-where-darwin-was-born"},
{"id":"pe-28","cat":"people","name":"Woolsthorpe, where Newton was born","lat":52.81,"lon":-0.63,"note":"A hamlet in Lincolnshire where Isaac Newton was born on Christmas Day 1642 in a manor house whose apple tree still stands.","country":"the United Kingdom","region":"Europe","about":"woolsthorpe-where-newton-was-born"},
{"id":"pe-29","cat":"people","name":"Pisa, where Galileo was born","lat":43.72,"lon":10.4,"note":"The Tuscan city of the leaning tower, where Galileo was born in 1564 and, legend says, dropped weights from the tower.","country":"Italy","region":"Europe","about":"pisa-where-galileo-was-born"},
{"id":"pe-30","cat":"people","name":"Toruń, where Copernicus was born","lat":53.01,"lon":18.6,"note":"A Hanseatic city on the Vistula in Poland, where Copernicus was born in 1473; its gingerbread and brick Gothic are the other claims.","country":"Poland","region":"Europe","about":"torun-where-copernicus-was-born"},
{"id":"pe-31","cat":"people","name":"Kaliningrad (Königsberg), where Kant lived his whole life","lat":54.71,"lon":20.51,"note":"The former Prussian capital, now a Russian exclave on the Baltic, where Kant was born in 1724 and died in 1804, never travelling more than a few miles from it.","country":"Russia","region":"Europe","about":"kaliningrad-konigsberg-where-kant-lived-his-whole-life"},
{"id":"pe-32","cat":"people","name":"Frankfurt, where Goethe was born","lat":50.11,"lon":8.68,"note":"Germany's financial capital on the Main, home of the ECB and the Bundesbank, where Goethe was born in 1749; the house was rebuilt after the war.","country":"Germany","region":"Europe","about":"frankfurt-where-goethe-was-born"},
{"id":"pe-33","cat":"people","name":"Yasnaya Polyana, Tolstoy's estate","lat":54.07,"lon":37.52,"note":"The estate near Tula, 200 km south of Moscow, where Tolstoy was born in 1828, wrote War and Peace and Anna Karenina, and is buried under the trees.","country":"Russia","region":"Europe","about":"yasnaya-polyana-tolstoy-s-estate"},
{"id":"pe-34","cat":"people","name":"Alcalá de Henares, where Cervantes was born","lat":40.48,"lon":-3.37,"note":"A university town east of Madrid where Cervantes was born in 1547; the university founded in 1499 is a UNESCO site.","country":"Spain","region":"Europe","about":"alcala-de-henares-where-cervantes-was-born"},
{"id":"pe-35","cat":"people","name":"Pretoria, where Elon Musk was born","lat":-25.75,"lon":28.19,"note":"South Africa's administrative capital, where Elon Musk was born in 1971; he left for Canada at 17.","country":"South Africa","region":"Africa","about":"pretoria-where-elon-musk-was-born"},
{"id":"pe-36","cat":"people","name":"Omaha, where Warren Buffett was born","lat":41.26,"lon":-95.93,"note":"Nebraska's largest city on the Missouri, where Warren Buffett was born in 1930 and still runs Berkshire Hathaway, whose May meeting fills the city.","country":"the United States","region":"North America","about":"omaha-where-warren-buffett-was-born"},
{"id":"pe-37","cat":"people","name":"Oak Park, where Hemingway was born","lat":41.89,"lon":-87.79,"note":"A suburb of Chicago where Hemingway was born in 1899, and where Frank Lloyd Wright built his first houses.","country":"the United States","region":"North America","about":"oak-park-where-hemingway-was-born"},
{"id":"pe-38","cat":"people","name":"Coyoacán, where Frida Kahlo was born","lat":19.35,"lon":-99.16,"note":"A district of southern Mexico City where Frida Kahlo was born in 1907 and died in 1954 in the Blue House, now her museum; Trotsky was murdered a few streets away.","country":"Mexico","region":"North America","about":"coyoacan-where-frida-kahlo-was-born"},
{"id":"pe-39","cat":"people","name":"Aracataca, where García Márquez was born","lat":10.59,"lon":-74.19,"note":"A small town in Colombia's banana country where Gabriel García Márquez was born in 1927; it became Macondo in One Hundred Years of Solitude.","country":"Colombia","region":"South America","about":"aracataca-where-garcia-marquez-was-born"},
{"id":"pe-40","cat":"people","name":"Balkh, where Rumi was born","lat":36.76,"lon":66.9,"note":"An ancient city in northern Afghanistan, Alexander's Bactra, where the poet Rumi was born in 1207 before his family fled the Mongols west to Konya.","country":"Afghanistan","region":"Asia","about":"balkh-where-rumi-was-born"},
{"id":"pe-41","cat":"people","name":"Tangier, where Ibn Battuta was born","lat":35.78,"lon":-5.81,"note":"The Moroccan port at the Strait of Gibraltar where Ibn Battuta was born in 1304; he set out at 21 and travelled 120,000 km over 30 years.","country":"Morocco","region":"Africa","about":"tangier-where-ibn-battuta-was-born"},
{"id":"pe-42","cat":"people","name":"Kunming, where Zheng He was born","lat":25.04,"lon":102.71,"note":"The capital of Yunnan in south-west China, the city of eternal spring, where the admiral Zheng He was born in 1371 to a Muslim family before leading the treasure fleets.","country":"China","region":"Asia","about":"kunming-where-zheng-he-was-born"},
{"id":"pe-43","cat":"people","name":"Alexandria, where Cleopatra was born","lat":31.2,"lon":29.92,"note":"Egypt's second city on the Mediterranean, founded by Alexander in 331 BC, where Cleopatra was born in 69 BC; the lighthouse and library are long gone.","country":"Egypt","region":"Africa","about":"alexandria-where-cleopatra-was-born"},
{"id":"pe-44","cat":"people","name":"Carthage, Hannibal's city","lat":36.86,"lon":10.33,"note":"The Phoenician city on the Bay of Tunis, Rome's great rival, where Hannibal was born in 247 BC; destroyed in 146 BC and now a suburb of Tunis.","country":"Tunisia","region":"Africa","about":"carthage-hannibal-s-city"},
{"id":"pe-45","cat":"people","name":"Tikrit, where Saladin was born","lat":34.6,"lon":43.68,"note":"A city on the Tigris north of Baghdad where Saladin was born in 1137, Kurdish by family; also Saddam Hussein's home town.","country":"Iraq","region":"Asia","about":"tikrit-where-saladin-was-born"},
{"id":"pe-46","cat":"people","name":"Khentii, where Genghis Khan was born","lat":48.9,"lon":110,"note":"The province in eastern Mongolia where Temüjin was born about 1162 near the Onon River; his burial place has never been found.","country":"Mongolia","region":"Asia","about":"khentii-where-genghis-khan-was-born"},
{"id":"pe-47","cat":"people","name":"Samarkand, Timur's capital","lat":39.65,"lon":66.98,"note":"The Silk Road city in Uzbekistan that Timur made his capital in 1370, with the Registan's three madrasas and his turquoise-domed tomb.","country":"Uzbekistan","region":"Asia","about":"samarkand-timur-s-capital"},
{"id":"ge-01","cat":"geo","name":"Everest","lat":27.99,"lon":86.93,"note":"The highest mountain on Earth at 8,849 m, on the border of Nepal and Tibet, first climbed by Hillary and Tenzing in 1953.","country":"China","region":"Asia","about":"everest"},
{"id":"ge-02","cat":"geo","name":"Kilimanjaro","lat":-3.07,"lon":37.36,"note":"Africa's highest mountain at 5,895 m, a dormant volcano in Tanzania rising alone from the plains, its glaciers shrinking.","country":"Tanzania","region":"Africa","about":"kilimanjaro"},
{"id":"ge-03","cat":"geo","name":"Mont Blanc","lat":45.83,"lon":6.86,"note":"The highest mountain in the Alps and western Europe at 4,806 m, on the French–Italian border above Chamonix, first climbed in 1786.","country":"Italy","region":"Europe","about":"mont-blanc"},
{"id":"ge-04","cat":"geo","name":"The Matterhorn","lat":45.98,"lon":7.66,"note":"The pyramidal peak of 4,478 m above Zermatt on the Swiss–Italian border, first climbed in 1865 at the cost of four lives on the descent.","country":"Switzerland","region":"Europe","about":"matterhorn"},
{"id":"ge-05","cat":"geo","name":"Aconcagua","lat":-32.65,"lon":-70.01,"note":"The highest mountain outside Asia at 6,961 m, in the Andes of Argentina near the Chilean border.","country":"Argentina","region":"South America","about":"aconcagua"},
{"id":"ge-06","cat":"geo","name":"Denali","lat":63.07,"lon":-151.01,"note":"North America's highest mountain at 6,190 m, in Alaska, called Mount McKinley from 1917 to 2015.","country":"the United States","region":"North America","about":"denali"},
{"id":"ge-07","cat":"geo","name":"Elbrus","lat":43.35,"lon":42.44,"note":"Europe's highest mountain at 5,642 m, a dormant volcano in the Caucasus of southern Russia.","country":"Russia","region":"Europe","about":"elbrus"},
{"id":"ge-08","cat":"geo","name":"Mount Fuji","lat":35.36,"lon":138.73,"note":"Japan's highest mountain at 3,776 m, a symmetrical volcano 100 km from Tokyo, last erupted in 1707, climbed by 200,000 people each summer.","country":"Japan","region":"Asia","about":"mount-fuji"},
{"id":"ge-09","cat":"geo","name":"Lake Baikal","lat":53.5,"lon":108,"note":"The deepest lake on Earth at 1,642 m, in Siberia, holding a fifth of the world's unfrozen fresh water, 25 million years old.","country":"Russia","region":"Asia","about":"lake-baikal"},
{"id":"ge-10","cat":"geo","name":"Lake Titicaca","lat":-15.9,"lon":-69.3,"note":"The highest navigable lake in the world at 3,812 m, between Peru and Bolivia, the Inca's place of creation.","country":"Peru","region":"South America","about":"lake-titicaca"},
{"id":"ge-11","cat":"geo","name":"Lake Victoria","lat":-1,"lon":33,"note":"Africa's largest lake and the source of the White Nile, shared by Uganda, Kenya and Tanzania, the size of Ireland.","country":"Tanzania","region":"Africa","about":"lake-victoria"},
{"id":"ge-12","cat":"geo","name":"Victoria Falls","lat":-17.92,"lon":25.86,"note":"The Zambezi's fall of 108 m on the Zambia–Zimbabwe border, the largest sheet of falling water in the world, 'the smoke that thunders'.","country":"Zimbabwe","region":"Africa","about":"victoria-falls"},
{"id":"ge-13","cat":"geo","name":"The Iguazu Falls","lat":-25.69,"lon":-54.44,"note":"275 falls along nearly 3 km of the Iguazu River on the Argentina–Brazil border, the Devil's Throat at their centre.","country":"Argentina","region":"South America","about":"the-iguazu-falls"},
{"id":"ge-14","cat":"geo","name":"Angel Falls","lat":5.97,"lon":-62.54,"note":"The world's highest waterfall at 979 m, dropping off a tabletop mountain in Venezuela's Gran Sabana, named for the pilot who found it in 1933.","country":"Venezuela","region":"South America","about":"angel-falls"},
{"id":"ge-15","cat":"geo","name":"The mouth of the Nile","lat":31.4,"lon":30.4,"note":"The Nile's delta on the Mediterranean, between Alexandria and Port Said, where the river that waters Egypt ends after 6,650 km.","country":"Egypt","region":"Africa","about":"the-mouth-of-the-nile"},
{"id":"ge-16","cat":"geo","name":"The mouth of the Amazon","lat":-0.5,"lon":-50,"note":"Where the world's largest river by volume meets the Atlantic in Brazil, 320 km wide, around the island of Marajó, the size of Switzerland.","country":"Brazil","region":"South America","about":"the-mouth-of-the-amazon"},
{"id":"ge-17","cat":"geo","name":"The mouth of the Mississippi","lat":29.15,"lon":-89.25,"note":"The bird's-foot delta south of New Orleans where the Mississippi reaches the Gulf of Mexico; the river carries 60% of US grain exports to the terminals here.","country":"the United States","region":"North America","about":"the-mouth-of-the-mississippi"},
{"id":"ge-18","cat":"geo","name":"The mouth of the Rhine","lat":51.98,"lon":4.12,"note":"Where the Rhine reaches the North Sea at Hook of Holland, by the port of Rotterdam, after 1,233 km from the Swiss Alps.","country":"the Netherlands","region":"Europe","about":"the-mouth-of-the-rhine"},
{"id":"ge-19","cat":"geo","name":"The Danube delta","lat":45.1,"lon":29.6,"note":"Europe's largest wetland, where the Danube ends in the Black Sea in Romania, a UNESCO reserve and the outlet for the river's barge trade.","country":"Romania","region":"Europe","about":"the-danube-delta"},
{"id":"ge-20","cat":"geo","name":"The Mekong delta","lat":10,"lon":106,"note":"Vietnam's rice bowl, where the Mekong fans into the South China Sea; it grows half the country's rice and most of its exports.","country":"Vietnam","region":"Asia","about":"the-mekong-delta"},
{"id":"ge-21","cat":"geo","name":"The mouth of the Yangtze","lat":31.4,"lon":121.9,"note":"Where China's longest river meets the East China Sea at Shanghai, after 6,300 km; the Yangtze delta is the country's economic heartland.","country":"China","region":"Asia","about":"the-mouth-of-the-yangtze"},
{"id":"ge-22","cat":"geo","name":"Tamanrasset, in the Sahara","lat":22.79,"lon":5.52,"note":"A town in the Hoggar Mountains of southern Algeria, in the deep Sahara, the gateway for Tuareg trade and the trans-Saharan routes.","country":"Algeria","region":"Africa","about":"tamanrasset-in-the-sahara"},
{"id":"ge-23","cat":"geo","name":"Dalanzadgad, in the Gobi","lat":43.57,"lon":104.43,"note":"The capital of Ömnögovi province in Mongolia's Gobi Desert, near the Oyu Tolgoi copper mine and the Tavan Tolgoi coalfield.","country":"Mongolia","region":"Asia","about":"dalanzadgad-in-the-gobi"},
{"id":"ge-24","cat":"geo","name":"San Pedro de Atacama","lat":-22.91,"lon":-68.2,"note":"An oasis town in Chile's Atacama Desert at 2,400 m, the driest place on Earth, near the lithium brines of the Salar de Atacama.","country":"Chile","region":"South America","about":"san-pedro-de-atacama"},
{"id":"ge-25","cat":"geo","name":"Sossusvlei, in the Namib","lat":-24.73,"lon":15.34,"note":"A salt and clay pan among the highest sand dunes in the world, in the Namib Desert of Namibia, the oldest desert on Earth.","country":"Namibia","region":"Africa","about":"sossusvlei-in-the-namib"},
{"id":"ge-26","cat":"geo","name":"The Great Barrier Reef","lat":-18.29,"lon":147.7,"note":"The world's largest coral reef system, 2,300 km along Australia's north-east coast, visible from space and bleaching with warmer seas.","country":"Australia","region":"Oceania","about":"great-barrier-reef"},
{"id":"ge-27","cat":"geo","name":"The Galápagos","lat":-0.78,"lon":-91,"note":"The volcanic archipelago on the equator 1,000 km off Ecuador where Darwin's finches led him toward natural selection in 1835.","country":"Ecuador","region":"South America","about":"the-galapagos"},
{"id":"ge-28","cat":"geo","name":"Svalbard","lat":78.22,"lon":15.63,"note":"The Norwegian archipelago halfway to the North Pole, with the Global Seed Vault at Longyearbyen and more polar bears than people.","country":"Svalbard","region":"the Arctic","about":"svalbard"},
{"id":"ge-29","cat":"geo","name":"Ushuaia","lat":-54.8,"lon":-68.3,"note":"The southernmost city in the world, on the Beagle Channel in Tierra del Fuego, Argentina, the port for Antarctic cruises.","country":"Argentina","region":"South America","about":"ushuaia"},
{"id":"ge-30","cat":"geo","name":"Cape Horn","lat":-55.98,"lon":-67.27,"note":"The southern tip of the Americas on an island of Chile, the dreaded rounding for sailing ships before the Panama Canal.","country":"Chile","region":"South America","about":"cape-horn"},
{"id":"ge-31","cat":"geo","name":"The Mariana Trench","lat":11.35,"lon":142.2,"note":"The deepest point in the oceans, 10,935 m at the Challenger Deep, east of the Mariana Islands in the western Pacific.","country":"the Mariana Islands","region":"the Pacific","about":"the-mariana-trench"},
{"id":"ge-32","cat":"geo","name":"Uluru","lat":-25.34,"lon":131.04,"note":"The sandstone monolith rising 348 m from the desert of central Australia, sacred to the Anangu, 450 km from Alice Springs.","country":"Australia","region":"Oceania","about":"uluru"},
{"id":"ge-33","cat":"geo","name":"The Grand Canyon","lat":36.1,"lon":-112.11,"note":"The Colorado River's gorge in Arizona, 446 km long and up to 1.8 km deep, cut through two billion years of rock.","country":"the United States","region":"North America","about":"grand-canyon"},
{"id":"ge-34","cat":"geo","name":"Yellowstone","lat":44.43,"lon":-110.59,"note":"The world's first national park, in Wyoming, on top of a supervolcano: geysers, hot springs and the bison herds.","country":"the United States","region":"North America","about":"yellowstone"},
{"id":"ge-35","cat":"geo","name":"Krakatoa","lat":-6.1,"lon":105.42,"note":"The volcano in the strait between Java and Sumatra whose 1883 eruption was heard 4,800 km away and killed 36,000, mostly by tsunami.","country":"Indonesia","region":"Asia","about":"krakatoa"},
{"id":"ge-36","cat":"geo","name":"Vesuvius","lat":40.82,"lon":14.43,"note":"The volcano above Naples that buried Pompeii and Herculaneum in AD 79; three million people live on its slopes.","country":"Italy","region":"Europe","about":"vesuvius"},
{"id":"ge-37","cat":"geo","name":"Etna","lat":37.75,"lon":14.99,"note":"Europe's most active volcano, 3,350 m above eastern Sicily, erupting almost continuously; vines grow on its lava.","country":"Italy","region":"Europe","about":"etna"},
{"id":"ge-38","cat":"geo","name":"Eyjafjallajökull","lat":63.63,"lon":-19.62,"note":"The Icelandic volcano under a glacier whose 2010 ash cloud grounded European air travel for six days.","country":"Iceland","region":"Europe","about":"eyjafjallajokull"},
{"id":"ge-39","cat":"geo","name":"The Dead Sea","lat":31.5,"lon":35.5,"note":"The salt lake between Israel, Jordan and the West Bank, the lowest point on land at 430 m below sea level, ten times saltier than the ocean; potash is mined from its brine.","country":"Jordan","region":"Asia","about":"dead-sea"},
{"id":"ge-40","cat":"geo","name":"The Aral Sea","lat":45,"lon":59.5,"note":"Once the world's fourth-largest lake, between Kazakhstan and Uzbekistan, drained to a tenth of its size by Soviet cotton irrigation.","country":"Uzbekistan","region":"Asia","about":"the-aral-sea"},
{"id":"ge-41","cat":"geo","name":"Chernobyl","lat":51.39,"lon":30.1,"note":"The nuclear plant in northern Ukraine whose reactor 4 exploded in 1986, the worst nuclear accident in history; the exclusion zone is still 2,600 km².","country":"Ukraine","region":"Europe","about":"chernobyl"},
{"id":"ge-42","cat":"geo","name":"Fukushima","lat":37.42,"lon":141.03,"note":"The nuclear plant on Japan's north-east coast flooded by the 2011 tsunami, causing three meltdowns and the shutdown of Japan's nuclear fleet.","country":"Japan","region":"Asia","about":"fukushima"},
{"id":"ge-43","cat":"geo","name":"Greenwich","lat":51.48,"lon":0,"note":"The district of London on the Thames whose observatory marks the prime meridian, 0° longitude, and gave the world GMT.","country":"the United Kingdom","region":"Europe","about":"greenwich"},
{"id":"ge-44","cat":"geo","name":"Timbuktu","lat":16.77,"lon":-3.01,"note":"The city on the edge of the Sahara in Mali, a centre of Islamic learning and the gold and salt trade in the 14th and 15th centuries.","country":"Mali","region":"Africa","about":"timbuktu"},
{"id":"ge-45","cat":"geo","name":"Kashgar","lat":39.47,"lon":75.99,"note":"The oasis city at the western end of China's Xinjiang, where the Silk Road's routes met before the Pamirs; a Uyghur city with a Sunday market.","country":"China","region":"Asia","about":"kashgar"},
{"id":"ge-46","cat":"geo","name":"Zanzibar","lat":-6.16,"lon":39.19,"note":"The island off Tanzania whose Stone Town ran the Indian Ocean's clove and slave trade under the Omani sultans; cloves still grow there.","country":"Tanzania","region":"Africa","about":"zanzibar"},
{"id":"ge-47","cat":"geo","name":"Bali","lat":-8.4,"lon":115.2,"note":"The Hindu island of Indonesia east of Java, rice terraces, temples and surf, and the country's tourist economy.","country":"Indonesia","region":"Asia","about":"bali"},
{"id":"ge-48","cat":"geo","name":"Socotra","lat":12.5,"lon":54,"note":"A Yemeni island in the Arabian Sea with dragon's blood trees found nowhere else, a third of its plants unique.","country":"Yemen","region":"the Indian Ocean","about":"socotra"},
{"id":"ge-49","cat":"geo","name":"Tristan da Cunha","lat":-37.1,"lon":-12.3,"note":"The most remote inhabited island on Earth, a British volcano in the South Atlantic 2,400 km from St Helena, with about 240 people.","country":"United Kingdom (overseas)","region":"the South Atlantic","about":"tristan-da-cunha"},
{"id":"ge-50","cat":"geo","name":"Pitcairn","lat":-25.07,"lon":-130.1,"note":"The Pacific island where the Bounty mutineers settled in 1790; their 50 descendants are the smallest national population in the world.","country":"United Kingdom (overseas)","region":"the Pacific","about":"pitcairn"},
{"id":"ge-51","cat":"geo","name":"Diego Garcia","lat":-7.31,"lon":72.41,"note":"The atoll in the Chagos Islands of the Indian Ocean, a US military base since the 1970s, whose islanders were removed; Britain agreed to return the islands to Mauritius in 2024.","country":"the Chagos Islands","region":"the Indian Ocean","about":"diego-garcia"},
{"id":"ge-52","cat":"geo","name":"Guam","lat":13.44,"lon":144.79,"note":"The largest of the Mariana Islands and a US territory in the western Pacific, a naval and air base 2,500 km from Tokyo and Manila.","country":"the United States (Pacific)","region":"the Pacific","about":"guam"},
{"id":"ge-53","cat":"geo","name":"Okinawa","lat":26.33,"lon":127.8,"note":"Japan's southern island chain, the Ryukyus, with most of the US bases in Japan; the site of the last great battle of 1945.","country":"Japan","region":"Asia","about":"okinawa"},
{"id":"ge-54","cat":"geo","name":"Petropavlovsk-Kamchatsky","lat":53.02,"lon":158.65,"note":"The city on Russia's Kamchatka peninsula, among volcanoes on the Pacific, reachable only by sea or air, a submarine base and salmon port.","country":"Russia","region":"Asia","about":"petropavlovsk-kamchatsky"},
{"id":"ge-55","cat":"geo","name":"McMurdo Station","lat":-77.85,"lon":166.67,"note":"The largest base in Antarctica, American, on Ross Island, with up to 1,200 people in summer, the hub for the South Pole.","country":"Antarctica","region":"Antarctica","about":"mcmurdo-station"},
{"id":"ge-56","cat":"geo","name":"Vostok Station","lat":-78.46,"lon":106.84,"note":"Russia's station on the East Antarctic ice sheet at 3,500 m, where the coldest temperature on Earth, −89.2 °C, was recorded in 1983, above a lake under 4 km of ice.","country":"Antarctica","region":"Antarctica","about":"vostok-station"},
{"id":"ge-57","cat":"geo","name":"Thule (Pituffik)","lat":76.53,"lon":-68.7,"note":"The US air and space base in north-west Greenland, 1,200 km north of the Arctic Circle, with the early-warning radar of the Cold War.","country":"Greenland","region":"the Arctic","about":"thule-pituffik"},
{"id":"ge-58","cat":"geo","name":"Nuuk","lat":64.18,"lon":-51.72,"note":"Greenland's capital on the west coast, about 19,000 people, the world's smallest capital by population among large territories; fish, and the minerals the great powers want.","country":"Greenland","region":"the Arctic","about":"nuuk"},
{"id":"ge-59","cat":"geo","name":"Longyearbyen","lat":78.22,"lon":15.63,"note":"The main town of Svalbard at 78°N, the northernmost town in the world, a former coal settlement with the Global Seed Vault in the mountain above it.","country":"Svalbard","region":"the Arctic","about":"longyearbyen"},
{"id":"ge-60","cat":"geo","name":"Murmansk","lat":68.97,"lon":33.08,"note":"The largest city in the Arctic, Russia's ice-free port on the Barents Sea, the base of the Northern Fleet and the start of the Northern Sea Route.","country":"Russia","region":"Europe","about":"murmansk"},
{"id":"ge-61","cat":"geo","name":"Yakutsk","lat":62.03,"lon":129.73,"note":"The capital of Russia's Sakha Republic, the coldest major city on Earth, on permafrost, with diamonds (Alrosa) and gold in the region.","country":"Russia","region":"Asia","about":"yakutsk"},
{"id":"ge-62","cat":"geo","name":"Vladivostok","lat":43.12,"lon":131.89,"note":"Russia's Pacific port and naval base, the end of the Trans-Siberian Railway, 9,300 km from Moscow and an hour from China.","country":"Russia","region":"Asia","about":"vladivostok"},
{"id":"ge-63","cat":"geo","name":"Darwin, Australia","lat":-12.46,"lon":130.84,"note":"The capital of Australia's Northern Territory on the Timor Sea, the closest Australian city to Asia, with the Ichthys LNG plant.","country":"Australia","region":"Oceania","about":"darwin-australia"},
{"id":"ge-64","cat":"geo","name":"Papeete","lat":-17.53,"lon":-149.57,"note":"The capital of French Polynesia on Tahiti, in the middle of the Pacific, the port for the black pearl and the islands' tourism.","country":"French Polynesia","region":"the Pacific","about":"papeete"},
{"id":"ge-65","cat":"geo","name":"Suva","lat":-18.14,"lon":178.44,"note":"Fiji's capital on Viti Levu, the largest city in the South Pacific islands, a sugar and tourism economy.","country":"Fiji","region":"Oceania","about":"suva"},
{"id":"ge-66","cat":"geo","name":"Port Moresby","lat":-9.44,"lon":147.18,"note":"Papua New Guinea's capital on the Gulf of Papua, with the country's LNG exports from the highlands' gas and the Porgera gold mine inland.","country":"Papua New Guinea","region":"Oceania","about":"port-moresby"},
{"id":"ge-67","cat":"geo","name":"Dili","lat":-8.56,"lon":125.57,"note":"The capital of East Timor, independent since 2002, on the north coast of Timor; the Timor Sea's oil and gas fund the state.","country":"Timor-Leste","region":"Asia","about":"dili"},
{"id":"ge-68","cat":"geo","name":"Malé","lat":4.17,"lon":73.51,"note":"The Maldives' capital, a city of 250,000 packed onto an island of 8 km², among the lowest-lying capitals in the world.","country":"the Maldives","region":"the Indian Ocean","about":"male"},
{"id":"ge-69","cat":"geo","name":"Port Louis","lat":-20.16,"lon":57.5,"note":"Mauritius's capital and port, a sugar island turned financial centre for Indian and African investment, with a rum and textile trade.","country":"Mauritius","region":"the Indian Ocean","about":"port-louis"},
{"id":"ge-70","cat":"geo","name":"Victoria, Seychelles","lat":-4.62,"lon":55.45,"note":"The capital of the Seychelles on Mahé, the smallest capital city in Africa, in an archipelago of 115 islands in the Indian Ocean.","country":"the Seychelles","region":"the Indian Ocean","about":"victoria-seychelles"},
{"id":"ge-71","cat":"geo","name":"Nouméa","lat":-22.28,"lon":166.46,"note":"The capital of New Caledonia, a French territory in the Pacific with a quarter of the world's nickel reserves and the smelters that process them.","country":"New Caledonia","region":"Oceania","about":"noumea"},
{"id":"ge-72","cat":"geo","name":"Lhasa","lat":29.65,"lon":91.12,"note":"Tibet's capital at 3,650 m, with the Potala Palace of the Dalai Lamas, reached by the world's highest railway since 2006.","country":"China","region":"Asia","about":"lhasa"},
{"id":"ge-73","cat":"geo","name":"Kathmandu","lat":27.72,"lon":85.32,"note":"Nepal's capital in a Himalayan valley at 1,400 m, the start of the Everest expeditions and a city of temples shaken by the 2015 earthquake.","country":"Nepal","region":"Asia","about":"kathmandu"},
{"id":"ge-74","cat":"geo","name":"Thimphu","lat":27.47,"lon":89.64,"note":"Bhutan's capital in a Himalayan valley, the country that measures gross national happiness and sells hydropower to India.","country":"Bhutan","region":"Asia","about":"thimphu"},
{"id":"ge-75","cat":"geo","name":"Ashgabat","lat":37.94,"lon":58.38,"note":"Turkmenistan's capital, a white-marble city at the edge of the Karakum Desert, built on the world's fourth-largest gas reserves, sold mostly to China.","country":"Turkmenistan","region":"Asia","about":"ashgabat"},
{"id":"ge-76","cat":"geo","name":"Bishkek","lat":42.87,"lon":74.59,"note":"Kyrgyzstan's capital below the Tien Shan, with the Kumtor gold mine supplying a tenth of the country's economy.","country":"Kyrgyzstan","region":"Asia","about":"bishkek"},
{"id":"ge-77","cat":"geo","name":"Dushanbe","lat":38.56,"lon":68.77,"note":"Tajikistan's capital, the poorest of the former Soviet states, with the Rogun dam under construction and aluminium smelted from imported alumina.","country":"Tajikistan","region":"Asia","about":"dushanbe"},
{"id":"ge-78","cat":"geo","name":"Vientiane","lat":17.97,"lon":102.6,"note":"Laos's capital on the Mekong facing Thailand, the 'battery of South-East Asia' selling hydropower, and the end of the China–Laos railway.","country":"Laos","region":"Asia","about":"vientiane"},
{"id":"ge-79","cat":"geo","name":"Phnom Penh","lat":11.55,"lon":104.92,"note":"Cambodia's capital where the Tonlé Sap meets the Mekong, rebuilt after the Khmer Rouge emptied it in 1975; garments and rice are the exports.","country":"Cambodia","region":"Asia","about":"phnom-penh"},
{"id":"ge-80","cat":"geo","name":"Naypyidaw","lat":19.76,"lon":96.08,"note":"Myanmar's purpose-built capital since 2005, a city of empty 20-lane boulevards 320 km north of Yangon, run by the military.","country":"Myanmar","region":"Asia","about":"naypyidaw"},
{"id":"ge-81","cat":"geo","name":"Bandar Seri Begawan","lat":4.9,"lon":114.94,"note":"Brunei's capital on Borneo, a sultanate of 450,000 people made rich by oil and gas, with a water village of stilt houses on the river.","country":"Brunei","region":"Asia","about":"bandar-seri-begawan"}
];
